-- =============================================================================
-- MIPS ERP Database Migration: 0001_schema.sql
-- Sub-phase 1A: Core PostgreSQL Schema, Security Constraints, Audit Logging & Indexes
-- =============================================================================

-- Enable required extensions
CREATE EXTENSION IF NOT EXISTS "uuid-ossp";
CREATE EXTENSION IF NOT EXISTS "pgcrypto";

-- =============================================================================
-- 1. Custom Types & Enums
-- =============================================================================

DO $$ BEGIN
    CREATE TYPE user_role AS ENUM ('admin', 'teacher', 'student');
EXCEPTION
    WHEN duplicate_object THEN null;
END $$;

DO $$ BEGIN
    CREATE TYPE student_status AS ENUM ('active', 'passed_out', 'discontinued', 'tc_issued');
EXCEPTION
    WHEN duplicate_object THEN null;
END $$;

DO $$ BEGIN
    CREATE TYPE exam_status AS ENUM ('draft', 'published');
EXCEPTION
    WHEN duplicate_object THEN null;
END $$;

DO $$ BEGIN
    CREATE TYPE attendance_session_status AS ENUM ('draft', 'submitted', 'locked');
EXCEPTION
    WHEN duplicate_object THEN null;
END $$;

DO $$ BEGIN
    CREATE TYPE attendance_status AS ENUM ('present', 'absent', 'late', 'leave');
EXCEPTION
    WHEN duplicate_object THEN null;
END $$;

DO $$ BEGIN
    CREATE TYPE payment_mode AS ENUM ('cash', 'upi', 'bank_transfer', 'cheque', 'other');
EXCEPTION
    WHEN duplicate_object THEN null;
END $$;

-- =============================================================================
-- 2. Utility Functions & Triggers
-- =============================================================================

-- Universal updated_at timestamp maintainer
CREATE OR REPLACE FUNCTION set_updated_at()
RETURNS TRIGGER AS $$
BEGIN
    NEW.updated_at = clock_timestamp();
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

-- Universal Audit Trigger Function
CREATE OR REPLACE FUNCTION audit_log_trigger()
RETURNS TRIGGER AS $$
DECLARE
    rec_id text;
    actor_id uuid;
    old_row jsonb := null;
    new_row jsonb := null;
    action_type text;
BEGIN
    BEGIN
        actor_id := auth.uid();
    EXCEPTION WHEN OTHERS THEN
        actor_id := null;
    END;

    IF TG_OP = 'INSERT' THEN
        action_type := 'INSERT';
        new_row := to_jsonb(NEW);
        rec_id := coalesce(NEW.id::text, '');
    ELSIF TG_OP = 'UPDATE' THEN
        IF NEW.deleted_at IS NOT NULL AND OLD.deleted_at IS NULL THEN
            action_type := 'SOFT_DELETE';
        ELSE
            action_type := 'UPDATE';
        END IF;
        old_row := to_jsonb(OLD);
        new_row := to_jsonb(NEW);
        rec_id := coalesce(NEW.id::text, OLD.id::text, '');
    ELSIF TG_OP = 'DELETE' THEN
        action_type := 'DELETE';
        old_row := to_jsonb(OLD);
        rec_id := coalesce(OLD.id::text, '');
    END IF;

    INSERT INTO audit_log (table_name, record_id, action, old_data, new_data, actor, created_at)
    VALUES (TG_TABLE_NAME, rec_id, action_type, old_row, new_row, actor_id, clock_timestamp());

    RETURN coalesce(NEW, OLD);
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- =============================================================================
-- 3. Core Master & Settings Tables
-- =============================================================================

-- Settings Table
CREATE TABLE IF NOT EXISTS settings (
    key text PRIMARY KEY,
    value text,
    description text,
    created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
    updated_at timestamptz NOT NULL DEFAULT clock_timestamp()
);

CREATE TRIGGER trg_settings_updated_at
BEFORE UPDATE ON settings
FOR EACH ROW EXECUTE FUNCTION set_updated_at();

-- Academic Years
CREATE TABLE IF NOT EXISTS academic_years (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    legacy_id bigint,
    year_name text NOT NULL UNIQUE,
    is_current boolean NOT NULL DEFAULT false,
    created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
    updated_at timestamptz NOT NULL DEFAULT clock_timestamp(),
    deleted_at timestamptz,
    deleted_by uuid REFERENCES auth.users(id)
);

CREATE TRIGGER trg_academic_years_updated_at
BEFORE UPDATE ON academic_years
FOR EACH ROW EXECUTE FUNCTION set_updated_at();

-- Universities / Boards
CREATE TABLE IF NOT EXISTS universities (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    legacy_id bigint,
    name text NOT NULL UNIQUE,
    created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
    updated_at timestamptz NOT NULL DEFAULT clock_timestamp(),
    deleted_at timestamptz,
    deleted_by uuid REFERENCES auth.users(id)
);

CREATE TRIGGER trg_universities_updated_at
BEFORE UPDATE ON universities
FOR EACH ROW EXECUTE FUNCTION set_updated_at();

-- Courses
CREATE TABLE IF NOT EXISTS courses (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    legacy_id bigint,
    name text NOT NULL,
    code text NOT NULL UNIQUE,
    university_id bigint REFERENCES universities(id),
    duration text,
    total_fee_paise bigint NOT NULL DEFAULT 0 CHECK (total_fee_paise >= 0),
    description text,
    status text NOT NULL DEFAULT 'active',
    created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
    updated_at timestamptz NOT NULL DEFAULT clock_timestamp(),
    deleted_at timestamptz,
    deleted_by uuid REFERENCES auth.users(id)
);

CREATE TRIGGER trg_courses_updated_at
BEFORE UPDATE ON courses
FOR EACH ROW EXECUTE FUNCTION set_updated_at();

-- Course Curriculum Subjects
CREATE TABLE IF NOT EXISTS course_subjects (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    legacy_id bigint,
    course_id bigint NOT NULL REFERENCES courses(id) ON DELETE CASCADE,
    semester text,
    subject_name text NOT NULL,
    subject_code text,
    max_marks numeric(5,2) NOT NULL CHECK (max_marks > 0),
    pass_marks numeric(5,2) NOT NULL CHECK (pass_marks >= 0 AND pass_marks <= max_marks),
    created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
    updated_at timestamptz NOT NULL DEFAULT clock_timestamp(),
    deleted_at timestamptz,
    deleted_by uuid REFERENCES auth.users(id)
);

CREATE TRIGGER trg_course_subjects_updated_at
BEFORE UPDATE ON course_subjects
FOR EACH ROW EXECUTE FUNCTION set_updated_at();

-- Batches
CREATE TABLE IF NOT EXISTS batches (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    legacy_id bigint,
    course_id bigint NOT NULL REFERENCES courses(id),
    batch_name text NOT NULL,
    start_date date,
    end_date date,
    created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
    updated_at timestamptz NOT NULL DEFAULT clock_timestamp(),
    deleted_at timestamptz,
    deleted_by uuid REFERENCES auth.users(id)
);

CREATE TRIGGER trg_batches_updated_at
BEFORE UPDATE ON batches
FOR EACH ROW EXECUTE FUNCTION set_updated_at();

-- =============================================================================
-- 4. User Profiles & Teachers
-- =============================================================================

-- Teachers
CREATE TABLE IF NOT EXISTS teachers (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    legacy_id bigint,
    name text NOT NULL,
    phone text,
    login_username text NOT NULL UNIQUE,
    status text NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'inactive')),
    deactivated_at timestamptz,
    deactivated_by uuid REFERENCES auth.users(id),
    created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
    updated_at timestamptz NOT NULL DEFAULT clock_timestamp(),
    deleted_at timestamptz,
    deleted_by uuid REFERENCES auth.users(id)
);

CREATE TRIGGER trg_teachers_updated_at
BEFORE UPDATE ON teachers
FOR EACH ROW EXECUTE FUNCTION set_updated_at();

-- Students
CREATE TABLE IF NOT EXISTS students (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    legacy_id bigint,
    admission_number text NOT NULL UNIQUE,
    registration_number text,
    name text NOT NULL,
    dob date,
    gender text NOT NULL DEFAULT 'Male' CHECK (gender IN ('Male', 'Female', 'Other')),
    phone text,
    email text,
    address text,
    admission_date date DEFAULT CURRENT_DATE,
    course_id bigint NOT NULL REFERENCES courses(id),
    batch_id bigint NOT NULL REFERENCES batches(id),
    university_id bigint REFERENCES universities(id),
    academic_year_id bigint REFERENCES academic_years(id),
    status student_status NOT NULL DEFAULT 'active',
    import_id text,
    created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
    updated_at timestamptz NOT NULL DEFAULT clock_timestamp(),
    deleted_at timestamptz,
    deleted_by uuid REFERENCES auth.users(id)
);

CREATE TRIGGER trg_students_updated_at
BEFORE UPDATE ON students
FOR EACH ROW EXECUTE FUNCTION set_updated_at();

-- User Profiles (Linked to Supabase auth.users)
CREATE TABLE IF NOT EXISTS profiles (
    user_id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE,
    role user_role NOT NULL,
    student_id bigint REFERENCES students(id) ON DELETE SET NULL,
    teacher_id bigint REFERENCES teachers(id) ON DELETE SET NULL,
    active boolean NOT NULL DEFAULT true,
    must_change_password boolean NOT NULL DEFAULT false,
    failed_attempts int NOT NULL DEFAULT 0,
    locked_at timestamptz,
    created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
    updated_at timestamptz NOT NULL DEFAULT clock_timestamp(),
    CONSTRAINT chk_profile_role_ref CHECK (
        (role = 'admin' AND student_id IS NULL AND teacher_id IS NULL) OR
        (role = 'teacher' AND teacher_id IS NOT NULL AND student_id IS NULL) OR
        (role = 'student' AND student_id IS NOT NULL AND teacher_id IS NULL)
    )
);

CREATE TRIGGER trg_profiles_updated_at
BEFORE UPDATE ON profiles
FOR EACH ROW EXECUTE FUNCTION set_updated_at();

-- Teacher Assignments
CREATE TABLE IF NOT EXISTS teacher_assignments (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    teacher_id bigint NOT NULL REFERENCES teachers(id) ON DELETE CASCADE,
    course_id bigint NOT NULL REFERENCES courses(id) ON DELETE CASCADE,
    batch_id bigint NOT NULL REFERENCES batches(id) ON DELETE CASCADE,
    subject_id bigint NOT NULL REFERENCES course_subjects(id) ON DELETE CASCADE,
    active boolean NOT NULL DEFAULT true,
    created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
    updated_at timestamptz NOT NULL DEFAULT clock_timestamp(),
    UNIQUE (teacher_id, batch_id, subject_id)
);

CREATE TRIGGER trg_teacher_assignments_updated_at
BEFORE UPDATE ON teacher_assignments
FOR EACH ROW EXECUTE FUNCTION set_updated_at();

-- =============================================================================
-- 5. Financial Management (Paise Precision)
-- =============================================================================

-- Student Fee Ledger Totals
CREATE TABLE IF NOT EXISTS fees (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    legacy_id bigint,
    student_id bigint NOT NULL UNIQUE REFERENCES students(id) ON DELETE CASCADE,
    total_fee_paise bigint NOT NULL DEFAULT 0 CHECK (total_fee_paise >= 0),
    paid_amount_paise bigint NOT NULL DEFAULT 0 CHECK (paid_amount_paise >= 0),
    pending_amount_paise bigint NOT NULL DEFAULT 0 CHECK (pending_amount_paise >= 0),
    created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
    updated_at timestamptz NOT NULL DEFAULT clock_timestamp(),
    deleted_at timestamptz,
    deleted_by uuid REFERENCES auth.users(id)
);

CREATE TRIGGER trg_fees_updated_at
BEFORE UPDATE ON fees
FOR EACH ROW EXECUTE FUNCTION set_updated_at();

-- Payments
CREATE TABLE IF NOT EXISTS payments (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    legacy_id bigint,
    student_id bigint NOT NULL REFERENCES students(id),
    amount_paise bigint NOT NULL CHECK (amount_paise > 0),
    payment_mode payment_mode NOT NULL DEFAULT 'cash',
    reference_number text,
    remarks text,
    date date NOT NULL DEFAULT CURRENT_DATE,
    is_cancelled boolean NOT NULL DEFAULT false,
    cancel_reason text,
    cancelled_at timestamptz,
    cancelled_by uuid REFERENCES auth.users(id),
    created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
    updated_at timestamptz NOT NULL DEFAULT clock_timestamp(),
    deleted_at timestamptz,
    deleted_by uuid REFERENCES auth.users(id)
);

CREATE TRIGGER trg_payments_updated_at
BEFORE UPDATE ON payments
FOR EACH ROW EXECUTE FUNCTION set_updated_at();

-- Receipts
CREATE TABLE IF NOT EXISTS receipts (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    legacy_id bigint,
    payment_id bigint NOT NULL UNIQUE REFERENCES payments(id) ON DELETE CASCADE,
    receipt_number text NOT NULL UNIQUE,
    created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
    updated_at timestamptz NOT NULL DEFAULT clock_timestamp(),
    deleted_at timestamptz,
    deleted_by uuid REFERENCES auth.users(id)
);

CREATE TRIGGER trg_receipts_updated_at
BEFORE UPDATE ON receipts
FOR EACH ROW EXECUTE FUNCTION set_updated_at();

-- =============================================================================
-- 6. Examinations, Marks & Results
-- =============================================================================

-- Exams
CREATE TABLE IF NOT EXISTS exams (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    legacy_id bigint,
    course_id bigint NOT NULL REFERENCES courses(id),
    batch_id bigint NOT NULL REFERENCES batches(id),
    academic_year_id bigint REFERENCES academic_years(id),
    name text NOT NULL,
    semester text,
    exam_date date,
    publish_date date,
    status exam_status NOT NULL DEFAULT 'draft',
    published_at timestamptz,
    created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
    updated_at timestamptz NOT NULL DEFAULT clock_timestamp(),
    deleted_at timestamptz,
    deleted_by uuid REFERENCES auth.users(id)
);

CREATE TRIGGER trg_exams_updated_at
BEFORE UPDATE ON exams
FOR EACH ROW EXECUTE FUNCTION set_updated_at();

-- Exam Subjects
CREATE TABLE IF NOT EXISTS exam_subjects (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    legacy_id bigint,
    exam_id bigint NOT NULL REFERENCES exams(id) ON DELETE CASCADE,
    name text NOT NULL,
    code text NOT NULL,
    max_marks numeric(5,2) NOT NULL CHECK (max_marks > 0),
    pass_marks numeric(5,2) NOT NULL CHECK (pass_marks >= 0 AND pass_marks <= max_marks),
    theory_marks numeric(5,2),
    practical_marks numeric(5,2),
    display_order int NOT NULL DEFAULT 0,
    created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
    updated_at timestamptz NOT NULL DEFAULT clock_timestamp(),
    deleted_at timestamptz,
    deleted_by uuid REFERENCES auth.users(id)
);

CREATE TRIGGER trg_exam_subjects_updated_at
BEFORE UPDATE ON exam_subjects
FOR EACH ROW EXECUTE FUNCTION set_updated_at();

-- Marks Matrix
CREATE TABLE IF NOT EXISTS marks (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    legacy_id bigint,
    exam_id bigint NOT NULL REFERENCES exams(id) ON DELETE CASCADE,
    subject_id bigint NOT NULL REFERENCES exam_subjects(id) ON DELETE CASCADE,
    student_id bigint NOT NULL REFERENCES students(id) ON DELETE CASCADE,
    marks_obtained numeric(5,2) CHECK (marks_obtained IS NULL OR marks_obtained >= 0),
    is_absent boolean NOT NULL DEFAULT false,
    grade text,
    status text,
    created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
    updated_at timestamptz NOT NULL DEFAULT clock_timestamp(),
    deleted_at timestamptz,
    deleted_by uuid REFERENCES auth.users(id),
    UNIQUE (exam_id, subject_id, student_id)
);

CREATE TRIGGER trg_marks_updated_at
BEFORE UPDATE ON marks
FOR EACH ROW EXECUTE FUNCTION set_updated_at();

-- Computed Results Transcripts
CREATE TABLE IF NOT EXISTS results (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    legacy_id bigint,
    exam_id bigint NOT NULL REFERENCES exams(id) ON DELETE CASCADE,
    student_id bigint NOT NULL REFERENCES students(id) ON DELETE CASCADE,
    total_marks numeric(6,2),
    percentage numeric(5,2),
    grade text,
    status text CHECK (status IN ('PASS', 'FAIL', 'PENDING', 'WITHHELD')),
    rank int,
    created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
    updated_at timestamptz NOT NULL DEFAULT clock_timestamp(),
    deleted_at timestamptz,
    deleted_by uuid REFERENCES auth.users(id),
    UNIQUE (exam_id, student_id)
);

CREATE TRIGGER trg_results_updated_at
BEFORE UPDATE ON results
FOR EACH ROW EXECUTE FUNCTION set_updated_at();

-- Grading Schemes (Configurable grade bands)
CREATE TABLE IF NOT EXISTS grading_schemes (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    legacy_id bigint,
    min_percent numeric(5,2) NOT NULL CHECK (min_percent >= 0),
    max_percent numeric(5,2) NOT NULL CHECK (max_percent <= 100 AND max_percent >= min_percent),
    grade text NOT NULL,
    is_pass boolean NOT NULL DEFAULT true,
    created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
    updated_at timestamptz NOT NULL DEFAULT clock_timestamp()
);

CREATE TRIGGER trg_grading_schemes_updated_at
BEFORE UPDATE ON grading_schemes
FOR EACH ROW EXECUTE FUNCTION set_updated_at();

-- =============================================================================
-- 7. Attendance Sessions & Records
-- =============================================================================

CREATE TABLE IF NOT EXISTS attendance_sessions (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    batch_id bigint NOT NULL REFERENCES batches(id) ON DELETE RESTRICT,
    subject_id bigint NOT NULL REFERENCES course_subjects(id) ON DELETE RESTRICT,
    date date NOT NULL,
    period int NOT NULL CHECK (period >= 1 AND period <= 10),
    status attendance_session_status NOT NULL DEFAULT 'draft',
    marked_by bigint REFERENCES teachers(id),
    submitted_at timestamptz,
    created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
    updated_at timestamptz NOT NULL DEFAULT clock_timestamp(),
    UNIQUE (batch_id, subject_id, date, period)
);

CREATE TRIGGER trg_attendance_sessions_updated_at
BEFORE UPDATE ON attendance_sessions
FOR EACH ROW EXECUTE FUNCTION set_updated_at();

CREATE TABLE IF NOT EXISTS attendance_records (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    session_id bigint NOT NULL REFERENCES attendance_sessions(id) ON DELETE CASCADE,
    student_id bigint NOT NULL REFERENCES students(id) ON DELETE RESTRICT,
    status attendance_status NOT NULL,
    remarks text,
    created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
    updated_at timestamptz NOT NULL DEFAULT clock_timestamp(),
    UNIQUE (session_id, student_id)
);

CREATE TRIGGER trg_attendance_records_updated_at
BEFORE UPDATE ON attendance_records
FOR EACH ROW EXECUTE FUNCTION set_updated_at();

-- Attendance Changes Audit (INSERT ONLY)
CREATE TABLE IF NOT EXISTS attendance_changes (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    record_id bigint NOT NULL REFERENCES attendance_records(id) ON DELETE CASCADE,
    old_status attendance_status NOT NULL,
    new_status attendance_status NOT NULL,
    changed_by uuid NOT NULL REFERENCES auth.users(id),
    changed_at timestamptz NOT NULL DEFAULT clock_timestamp(),
    reason text NOT NULL
);

-- =============================================================================
-- 8. Document Templates & Generated Document Metadata
-- =============================================================================

CREATE TABLE IF NOT EXISTS document_templates (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    legacy_id bigint,
    name text NOT NULL UNIQUE,
    content text NOT NULL,
    created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
    updated_at timestamptz NOT NULL DEFAULT clock_timestamp(),
    deleted_at timestamptz,
    deleted_by uuid REFERENCES auth.users(id)
);

CREATE TRIGGER trg_document_templates_updated_at
BEFORE UPDATE ON document_templates
FOR EACH ROW EXECUTE FUNCTION set_updated_at();

CREATE TABLE IF NOT EXISTS generated_documents (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    legacy_id bigint,
    student_id bigint NOT NULL REFERENCES students(id) ON DELETE CASCADE,
    template_id bigint NOT NULL REFERENCES document_templates(id),
    document_number text NOT NULL,
    date date NOT NULL DEFAULT CURRENT_DATE,
    created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
    updated_at timestamptz NOT NULL DEFAULT clock_timestamp(),
    deleted_at timestamptz,
    deleted_by uuid REFERENCES auth.users(id)
);

CREATE TRIGGER trg_generated_documents_updated_at
BEFORE UPDATE ON generated_documents
FOR EACH ROW EXECUTE FUNCTION set_updated_at();

-- =============================================================================
-- 9. Number Counters (Sequential Auto-Numbering Engine)
-- =============================================================================

CREATE TABLE IF NOT EXISTS number_counters (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    kind text NOT NULL,
    year int NOT NULL,
    last_value bigint NOT NULL DEFAULT 0,
    created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
    updated_at timestamptz NOT NULL DEFAULT clock_timestamp(),
    UNIQUE (kind, year)
);

CREATE TRIGGER trg_number_counters_updated_at
BEFORE UPDATE ON number_counters
FOR EACH ROW EXECUTE FUNCTION set_updated_at();

-- =============================================================================
-- 10. Notifications & Web Push Subscriptions
-- =============================================================================

CREATE TABLE IF NOT EXISTS notifications (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
    type text NOT NULL,
    title text NOT NULL,
    body text NOT NULL,
    link text,
    read_at timestamptz,
    created_at timestamptz NOT NULL DEFAULT clock_timestamp()
);

CREATE TABLE IF NOT EXISTS push_subscriptions (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
    endpoint text NOT NULL UNIQUE,
    p256dh text NOT NULL,
    auth text NOT NULL,
    created_at timestamptz NOT NULL DEFAULT clock_timestamp()
);

-- =============================================================================
-- 11. Immutable Audit Log (INSERT ONLY)
-- =============================================================================

CREATE TABLE IF NOT EXISTS audit_log (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    table_name text NOT NULL,
    record_id text NOT NULL,
    action text NOT NULL CHECK (action IN ('INSERT', 'UPDATE', 'DELETE', 'SOFT_DELETE')),
    old_data jsonb,
    new_data jsonb,
    actor uuid REFERENCES auth.users(id),
    created_at timestamptz NOT NULL DEFAULT clock_timestamp()
);

-- Revoke all UPDATE and DELETE rights on immutable tables
REVOKE UPDATE, DELETE ON audit_log FROM PUBLIC, anon, authenticated;
REVOKE UPDATE, DELETE ON attendance_changes FROM PUBLIC, anon, authenticated;

-- Attach Audit Triggers to Core Tables
CREATE TRIGGER trg_audit_students
AFTER INSERT OR UPDATE OR DELETE ON students
FOR EACH ROW EXECUTE FUNCTION audit_log_trigger();

CREATE TRIGGER trg_audit_courses
AFTER INSERT OR UPDATE OR DELETE ON courses
FOR EACH ROW EXECUTE FUNCTION audit_log_trigger();

CREATE TRIGGER trg_audit_batches
AFTER INSERT OR UPDATE OR DELETE ON batches
FOR EACH ROW EXECUTE FUNCTION audit_log_trigger();

CREATE TRIGGER trg_audit_fees
AFTER INSERT OR UPDATE OR DELETE ON fees
FOR EACH ROW EXECUTE FUNCTION audit_log_trigger();

CREATE TRIGGER trg_audit_payments
AFTER INSERT OR UPDATE OR DELETE ON payments
FOR EACH ROW EXECUTE FUNCTION audit_log_trigger();

CREATE TRIGGER trg_audit_receipts
AFTER INSERT OR UPDATE OR DELETE ON receipts
FOR EACH ROW EXECUTE FUNCTION audit_log_trigger();

CREATE TRIGGER trg_audit_exams
AFTER INSERT OR UPDATE OR DELETE ON exams
FOR EACH ROW EXECUTE FUNCTION audit_log_trigger();

CREATE TRIGGER trg_audit_marks
AFTER INSERT OR UPDATE OR DELETE ON marks
FOR EACH ROW EXECUTE FUNCTION audit_log_trigger();

CREATE TRIGGER trg_audit_results
AFTER INSERT OR UPDATE OR DELETE ON results
FOR EACH ROW EXECUTE FUNCTION audit_log_trigger();

CREATE TRIGGER trg_audit_attendance_sessions
AFTER INSERT OR UPDATE OR DELETE ON attendance_sessions
FOR EACH ROW EXECUTE FUNCTION audit_log_trigger();

-- =============================================================================
-- 12. Strategic Performance & Lookup Indexes
-- =============================================================================

-- Students
CREATE INDEX IF NOT EXISTS idx_students_course_batch ON students(course_id, batch_id) WHERE deleted_at IS NULL;
CREATE INDEX IF NOT EXISTS idx_students_adm_no ON students(admission_number);
CREATE INDEX IF NOT EXISTS idx_students_reg_no ON students(registration_number);
CREATE INDEX IF NOT EXISTS idx_students_dob ON students(dob);
CREATE INDEX IF NOT EXISTS idx_students_legacy_id ON students(legacy_id);

-- Fees & Payments
CREATE INDEX IF NOT EXISTS idx_fees_student ON fees(student_id) WHERE deleted_at IS NULL;
CREATE INDEX IF NOT EXISTS idx_fees_legacy_id ON fees(legacy_id);
CREATE INDEX IF NOT EXISTS idx_payments_student ON payments(student_id) WHERE deleted_at IS NULL;
CREATE INDEX IF NOT EXISTS idx_payments_date ON payments(date);
CREATE INDEX IF NOT EXISTS idx_payments_is_cancelled ON payments(is_cancelled);
CREATE INDEX IF NOT EXISTS idx_payments_legacy_id ON payments(legacy_id);
CREATE INDEX IF NOT EXISTS idx_receipts_number ON receipts(receipt_number);
CREATE INDEX IF NOT EXISTS idx_receipts_payment ON receipts(payment_id);
CREATE INDEX IF NOT EXISTS idx_receipts_legacy_id ON receipts(legacy_id);

-- Courses, Batches, Subjects
CREATE INDEX IF NOT EXISTS idx_courses_code ON courses(code);
CREATE INDEX IF NOT EXISTS idx_courses_legacy_id ON courses(legacy_id);
CREATE INDEX IF NOT EXISTS idx_course_subjects_course ON course_subjects(course_id) WHERE deleted_at IS NULL;
