-- supabase/migrations/0018_daily_timetables.sql
-- Phase 10B/10C: Day-by-Day Daily Timetable Architecture & RLS Safeguards

-- 1. daily_timetables: Track publication state per day
CREATE TABLE IF NOT EXISTS daily_timetables (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    date date NOT NULL UNIQUE,
    status text NOT NULL DEFAULT 'draft' CHECK (status IN ('draft', 'published', 'not_created')),
    published_at timestamptz,
    notify_users boolean NOT NULL DEFAULT true,
    created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
    updated_at timestamptz NOT NULL DEFAULT clock_timestamp()
);

-- 2. daily_timetable_entries: Scheduled class rows for each day
CREATE TABLE IF NOT EXISTS daily_timetable_entries (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    daily_timetable_id bigint REFERENCES daily_timetables(id) ON DELETE CASCADE,
    date date NOT NULL,
    course_id bigint REFERENCES courses(id) ON DELETE SET NULL,
    course_name text NOT NULL,
    year text NOT NULL DEFAULT '1st Year',
    teacher_id bigint REFERENCES teachers(id) ON DELETE SET NULL,
    teacher_name text NOT NULL,
    subject_id bigint REFERENCES course_subjects(id) ON DELETE SET NULL,
    subject_name text NOT NULL,
    class_room text NOT NULL,
    start_time text NOT NULL,
    end_time text NOT NULL,
    sort_order int DEFAULT 0,
    created_at timestamptz NOT NULL DEFAULT clock_timestamp()
);

CREATE INDEX IF NOT EXISTS idx_daily_timetables_date ON daily_timetables (date, status);
CREATE INDEX IF NOT EXISTS idx_daily_timetable_entries_date ON daily_timetable_entries (date);
CREATE INDEX IF NOT EXISTS idx_daily_timetable_entries_teacher ON daily_timetable_entries (teacher_name, date);

-- 3. RLS Policies
ALTER TABLE daily_timetables ENABLE ROW LEVEL SECURITY;
ALTER TABLE daily_timetable_entries ENABLE ROW LEVEL SECURITY;

-- Admin Policy: Full Access
CREATE POLICY "Admins have full access to daily_timetables"
ON daily_timetables FOR ALL
TO authenticated
USING (
    EXISTS (
        SELECT 1 FROM profiles 
        WHERE profiles.id = auth.uid() 
          AND profiles.role = 'admin' 
          AND profiles.active = true
    )
)
WITH CHECK (
    EXISTS (
        SELECT 1 FROM profiles 
        WHERE profiles.id = auth.uid() 
          AND profiles.role = 'admin' 
          AND profiles.active = true
    )
);

CREATE POLICY "Admins have full access to daily_timetable_entries"
ON daily_timetable_entries FOR ALL
TO authenticated
USING (
    EXISTS (
        SELECT 1 FROM profiles 
        WHERE profiles.id = auth.uid() 
          AND profiles.role = 'admin' 
          AND profiles.active = true
    )
)
WITH CHECK (
    EXISTS (
        SELECT 1 FROM profiles 
        WHERE profiles.id = auth.uid() 
          AND profiles.role = 'admin' 
          AND profiles.active = true
    )
);

-- Students & Teachers Read Policy:
-- Can ONLY read PUBLISHED days whose date is today or tomorrow (Asia/Kolkata timezone)
CREATE POLICY "Students and teachers can read published today and tomorrow daily_timetables"
ON daily_timetables FOR SELECT
TO authenticated
USING (
    status = 'published' AND
    date >= (CURRENT_TIMESTAMP AT TIME ZONE 'Asia/Kolkata')::date AND
    date <= ((CURRENT_TIMESTAMP AT TIME ZONE 'Asia/Kolkata')::date + 1)
);

CREATE POLICY "Students and teachers can read published today and tomorrow daily_timetable_entries"
ON daily_timetable_entries FOR SELECT
TO authenticated
USING (
    EXISTS (
        SELECT 1 FROM daily_timetables dt
        WHERE dt.date = daily_timetable_entries.date
          AND dt.status = 'published'
          AND dt.date >= (CURRENT_TIMESTAMP AT TIME ZONE 'Asia/Kolkata')::date
          AND dt.date <= ((CURRENT_TIMESTAMP AT TIME ZONE 'Asia/Kolkata')::date + 1)
    )
);

-- >>> END OF supabase/migrations\0018_daily_timetables.sql <<<


-- >>> START OF supabase/migrations\0019_semester_based_attendance_and_promotion.sql <<<

-- supabase/migrations/0019_semester_based_attendance_and_promotion.sql
-- Phase 12A: Semester-based Attendance, Semester Promotion & Derived Academic Year

-- =============================================================================
-- 1. Course Duration Helper Function
-- =============================================================================
CREATE OR REPLACE FUNCTION course_duration_years(p_course_id bigint)
RETURNS int AS $$
DECLARE
    v_dur text;
    v_years int;
BEGIN
    SELECT duration INTO v_dur FROM courses WHERE id = p_course_id;
    IF v_dur IS NULL THEN RETURN 2; END IF;
    v_years := coalesce(substring(v_dur from '[0-9]+')::int, 2);
    RETURN GREATEST(1, v_years);
END;
$$ LANGUAGE plpgsql STABLE;

-- =============================================================================
-- 2. Alter batches: Add current_semester & Generated current_year
-- =============================================================================
ALTER TABLE batches
    ADD COLUMN IF NOT EXISTS current_semester int NOT NULL DEFAULT 1 CHECK (current_semester >= 1);

-- Generated stored column for current_year: ceil(current_semester / 2)
DO $$
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM information_schema.columns 
        WHERE table_name = 'batches' AND column_name = 'current_year'
    ) THEN
        ALTER TABLE batches 
            ADD COLUMN current_year int GENERATED ALWAYS AS (ceil(current_semester::numeric / 2.0)::int) STORED;
    END IF;
END $$;

-- =============================================================================
-- 3. batch_semesters: Semester Date Ranges & Status per Batch
-- =============================================================================
CREATE TABLE IF NOT EXISTS batch_semesters (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    batch_id bigint NOT NULL REFERENCES batches(id) ON DELETE CASCADE,
    semester_no int NOT NULL CHECK (semester_no >= 1),
    start_date date NOT NULL,
    end_date date,
    status text NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'closed')),
    created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
    updated_at timestamptz NOT NULL DEFAULT clock_timestamp(),
    CONSTRAINT uk_batch_semester UNIQUE (batch_id, semester_no),
    CONSTRAINT chk_semester_dates CHECK (end_date IS NULL OR end_date >= start_date)
);

CREATE INDEX IF NOT EXISTS idx_batch_semesters_lookup 
    ON batch_semesters (batch_id, semester_no, status);

-- Trigger: Ensure non-overlapping semester dates per batch
CREATE OR REPLACE FUNCTION check_batch_semester_non_overlapping()
RETURNS TRIGGER AS $$
BEGIN
    IF EXISTS (
        SELECT 1 FROM batch_semesters
        WHERE batch_id = NEW.batch_id
          AND id != coalesce(NEW.id, -1)
          AND daterange(start_date, coalesce(end_date, '9999-12-31'::date), '[]') &&
              daterange(NEW.start_date, coalesce(NEW.end_date, '9999-12-31'::date), '[]')
    ) THEN
        RAISE EXCEPTION 'Semester date range [% to %] overlaps with an existing semester for batch %.',
            NEW.start_date, coalesce(NEW.end_date::text, 'ongoing'), NEW.batch_id;
    END IF;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS trg_check_batch_semester_dates ON batch_semesters;
CREATE TRIGGER trg_check_batch_semester_dates
    BEFORE INSERT OR UPDATE OF start_date, end_date ON batch_semesters
    FOR EACH ROW EXECUTE FUNCTION check_batch_semester_non_overlapping();

ALTER TABLE batch_semesters ENABLE ROW LEVEL SECURITY;

CREATE POLICY p_batch_semesters_all ON batch_semesters
    FOR ALL TO authenticated
    USING (true)
    WITH CHECK (
        EXISTS (
            SELECT 1 FROM profiles 
            WHERE profiles.id = auth.uid() AND profiles.role = 'admin' AND profiles.active = true
        )
    );

-- =============================================================================
-- 4. attendance_sessions: Add semester_no & Auto-Assignment Trigger
-- =============================================================================
ALTER TABLE attendance_sessions
    ADD COLUMN IF NOT EXISTS semester_no int;

CREATE INDEX IF NOT EXISTS idx_attendance_sessions_semester 
    ON attendance_sessions (batch_id, semester_no);

CREATE OR REPLACE FUNCTION assign_attendance_session_semester()
RETURNS TRIGGER AS $$
DECLARE
    v_sem_no int;
BEGIN
    -- Resolve semester from batch_semesters based on session date
    SELECT semester_no INTO v_sem_no
    FROM batch_semesters
    WHERE batch_id = NEW.batch_id
      AND NEW.date >= start_date
      AND (end_date IS NULL OR NEW.date <= end_date)
    ORDER BY semester_no DESC
    LIMIT 1;

    IF v_sem_no IS NULL THEN
        RAISE EXCEPTION 'Session date % is outside any semester date range for batch %. Please configure semester dates in Batch Management.',
            NEW.date, NEW.batch_id;
    END IF;

    NEW.semester_no := v_sem_no;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS trg_attendance_sessions_assign_semester ON attendance_sessions;
CREATE TRIGGER trg_attendance_sessions_assign_semester
    BEFORE INSERT OR UPDATE OF date, batch_id ON attendance_sessions
    FOR EACH ROW EXECUTE FUNCTION assign_attendance_session_semester();

-- =============================================================================
-- 5. Data Migration: Populate batch_semesters & Assign Existing Attendance
-- =============================================================================
DO $$
DECLARE
    r RECORD;
    v_initial_sem int;
    v_start date;
BEGIN
    FOR r IN SELECT * FROM batches WHERE deleted_at IS NULL LOOP
        v_start := coalesce(r.start_date, '2024-01-01'::date);
        v_initial_sem := coalesce(r.current_semester, 1);

        -- Insert initial semester if absent
        INSERT INTO batch_semesters (batch_id, semester_no, start_date, end_date, status)
        VALUES (r.id, v_initial_sem, v_start, NULL, 'active')
        ON CONFLICT (batch_id, semester_no) DO NOTHING;

        -- Assign existing attendance to this semester
        UPDATE attendance_sessions
        SET semester_no = v_initial_sem
        WHERE batch_id = r.id AND semester_no IS NULL;
    END LOOP;
END $$;

-- Check & log any batches where session dates precede semester start_date
CREATE OR REPLACE FUNCTION audit_inconsistent_batch_semester_dates()
RETURNS TABLE (
    batch_id bigint,
    batch_name text,
    semester_start date,
    earliest_session date,
    inconsistent_session_count int
) AS $$
BEGIN
    RETURN QUERY
    SELECT 
        b.id,
        b.batch_name,
        bs.start_date,
        min(s.date) AS earliest_session,
        count(s.id)::int AS inconsistent_session_count
    FROM batches b
    JOIN batch_semesters bs ON bs.batch_id = b.id AND bs.status = 'active'
    JOIN attendance_sessions s ON s.batch_id = b.id
    WHERE s.date < bs.start_date
    GROUP BY b.id, b.batch_name, bs.start_date;
END;
$$ LANGUAGE plpgsql STABLE;

-- =============================================================================
-- 6. attendance_alert_state: Key by (student_id, enrollment_id, semester_no)
-- =============================================================================
ALTER TABLE attendance_alert_state
    ADD COLUMN IF NOT EXISTS semester_no int NOT NULL DEFAULT 1;

DO $$
BEGIN
    ALTER TABLE attendance_alert_state DROP CONSTRAINT IF EXISTS attendance_alert_state_pkey;
    ALTER TABLE attendance_alert_state ADD PRIMARY KEY (student_id, enrollment_id, semester_no);
EXCEPTION WHEN OTHERS THEN
    NULL;
END $$;

-- =============================================================================
-- 7. student_attendance_summary(student_id, enrollment_id, semester_no)
-- =============================================================================
DROP FUNCTION IF EXISTS student_attendance_summary(bigint, bigint);
DROP FUNCTION IF EXISTS student_attendance_summary(bigint, bigint, int);

CREATE OR REPLACE FUNCTION student_attendance_summary(
    p_student_id bigint, 
    p_enrollment_id bigint DEFAULT NULL,
    p_semester_no int DEFAULT NULL
)
RETURNS TABLE (
    student_id bigint,
    enrollment_id bigint,
    semester_no int,
    sessions_held int,
    present_count int,
    late_count int,
    absent_count int,
    leave_count int,
    weighted_present numeric(10,2),
    percentage numeric(5,2),
    status_band text,
    can_miss_more int,
    recover_sessions int,
    absent_impact_pct numeric(5,2),
    late_impact_pct numeric(5,2)
) AS $$
DECLARE
    v_enr_id bigint;
    v_batch_id bigint;
    v_enrolled_on date;
    v_target_sem int;
    v_sem_start date;
    v_sem_end date;
    v_min_pct numeric := 75.0;
    v_rem_pct numeric := 80.0;
    v_late_wt numeric := 0.5;
    v_leave_mode text := 'excluded';
    v_setting text;

    v_total_held int := 0;
    v_present int := 0;
    v_late int := 0;
    v_absent int := 0;
    v_leave int := 0;
    v_effective_held int := 0;
    v_weighted numeric(10,2) := 0.0;
    v_pct numeric(5,2) := 100.0;
    v_band text := 'ok';
    v_miss int := 0;
    v_recover int := 0;
    v_absent_impact numeric(5,2) := 0.0;
    v_late_impact numeric(5,2) := 0.0;
BEGIN
    IF is_student() AND p_student_id != current_student_id() THEN
        RAISE EXCEPTION 'Access denied. You can only view your own attendance summary.';
    END IF;

    SELECT value INTO v_setting FROM settings WHERE key = 'min_attendance_percent';
    IF v_setting IS NOT NULL THEN v_min_pct := v_setting::numeric; END IF;

    SELECT value INTO v_setting FROM settings WHERE key = 'reminder_attendance_percent';
    IF v_setting IS NOT NULL THEN v_rem_pct := v_setting::numeric; END IF;

    SELECT value INTO v_setting FROM settings WHERE key = 'late_weight';
    IF v_setting IS NOT NULL THEN v_late_wt := v_setting::numeric; END IF;

    SELECT value INTO v_setting FROM settings WHERE key = 'leave_handling';
    IF v_setting IS NOT NULL THEN v_leave_mode := lower(trim(v_setting)); END IF;

    -- Resolve student's PRIMARY enrollment
    SELECT se.id, se.batch_id, se.enrolled_on, b.current_semester
    INTO v_enr_id, v_batch_id, v_enrolled_on, v_target_sem
    FROM student_enrollments se
    JOIN batches b ON b.id = se.batch_id
    JOIN courses c ON c.id = b.course_id
    WHERE se.student_id = p_student_id 
      AND (se.kind = 'primary' OR c.course_type = 'primary')
      AND se.status = 'active'
      AND se.deleted_at IS NULL
    ORDER BY se.id DESC LIMIT 1;

    IF v_batch_id IS NULL THEN
        SELECT s.batch_id, coalesce(s.admission_date, CURRENT_DATE), b.current_semester
        INTO v_batch_id, v_enrolled_on, v_target_sem
        FROM students s
        JOIN batches b ON b.id = s.batch_id
        JOIN courses c ON c.id = b.course_id
        WHERE s.id = p_student_id AND c.course_type = 'primary';
    END IF;

    IF v_batch_id IS NULL THEN RETURN; END IF;

    -- Default semester to batch current_semester
    IF p_semester_no IS NOT NULL THEN
        v_target_sem := p_semester_no;
    END IF;

    -- Get semester date boundaries
    SELECT start_date, end_date INTO v_sem_start, v_sem_end
    FROM batch_semesters
    WHERE batch_id = v_batch_id AND semester_no = v_target_sem;

    IF v_sem_start IS NULL THEN
        v_sem_start := v_enrolled_on;
    END IF;

    -- Total sessions held in this semester
    SELECT count(*)::int INTO v_total_held
    FROM attendance_sessions s
    JOIN batches b ON b.id = s.batch_id
    JOIN courses c ON c.id = b.course_id
    WHERE s.batch_id = v_batch_id
      AND c.course_type = 'primary'
      AND (s.semester_no = v_target_sem OR (s.date >= v_sem_start AND (v_sem_end IS NULL OR s.date <= v_sem_end)))
      AND s.date >= v_enrolled_on
      AND s.status IN ('submitted', 'locked');

    -- Tally student attendance records for this semester
    SELECT 
        count(*) FILTER (WHERE ar.status = 'present')::int,
        count(*) FILTER (WHERE ar.status = 'late')::int,
        count(*) FILTER (WHERE ar.status = 'absent')::int,
        count(*) FILTER (WHERE ar.status = 'leave')::int
    INTO v_present, v_late, v_absent, v_leave
    FROM attendance_records ar
    JOIN attendance_sessions s ON s.id = ar.session_id
    JOIN batches b ON b.id = s.batch_id
    JOIN courses c ON c.id = b.course_id
    WHERE ar.student_id = p_student_id
      AND s.batch_id = v_batch_id
      AND c.course_type = 'primary'
      AND (s.semester_no = v_target_sem OR (s.date >= v_sem_start AND (v_sem_end IS NULL OR s.date <= v_sem_end)))
      AND s.date >= v_enrolled_on
      AND s.status IN ('submitted', 'locked');

    -- Effective sessions
    IF v_leave_mode = 'counted_present' THEN
        v_effective_held := v_total_held;
        v_weighted := v_present + v_leave + (v_late * v_late_wt);
    ELSIF v_leave_mode = 'counted_absent' THEN
        v_effective_held := v_total_held;
        v_weighted := v_present + (v_late * v_late_wt);
    ELSE
        v_effective_held := GREATEST(0, v_total_held - v_leave);
        v_weighted := v_present + (v_late * v_late_wt);
    END IF;

    IF v_effective_held > 0 THEN
        v_pct := round((v_weighted / v_effective_held::numeric) * 100.0, 2);
    ELSE
        v_pct := 100.0;
    END IF;

    -- Band determination
    IF v_pct < v_min_pct THEN
        v_band := 'shortage';
    ELSIF v_pct < v_rem_pct THEN
        v_band := 'low';
    ELSE
        v_band := 'ok';
    END IF;

    -- can_miss_more & recover_sessions (Current semester only)
    IF v_effective_held > 0 THEN
        IF v_pct >= v_min_pct THEN
            v_miss := floor((v_weighted - (v_min_pct / 100.0) * v_effective_held) / (v_min_pct / 100.0))::int;
            v_miss := GREATEST(0, v_miss);
            v_recover := 0;
        ELSE
            v_miss := 0;
            v_recover := ceil(((v_min_pct / 100.0) * v_effective_held - v_weighted) / (1.0 - (v_min_pct / 100.0)))::int;
            v_recover := GREATEST(1, v_recover);
        END IF;

        v_absent_impact := round((1.0 / (v_effective_held + 1)::numeric) * 100.0, 2);
        v_late_impact := round(((1.0 - v_late_wt) / (v_effective_held + 1)::numeric) * 100.0, 2);
    END IF;

    RETURN QUERY SELECT
        p_student_id,
        v_enr_id,
        v_target_sem,
        v_effective_held,
        v_present,
        v_late,
        v_absent,
        v_leave,
        v_weighted,
        v_pct,
        v_band,
        v_miss,
        v_recover,
        v_absent_impact,
        v_late_impact;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER STABLE
SET search_path = public, pg_temp;

-- =============================================================================
-- 8. student_semesters_summary: All Semesters for a Student
-- =============================================================================
CREATE OR REPLACE FUNCTION student_semesters_summary(
    p_student_id bigint,
    p_enrollment_id bigint DEFAULT NULL
)
RETURNS TABLE (
    semester_no int,
    year_no int,
    start_date date,
    end_date date,
    status text,
    sessions_held int,
    present_count int,
    late_count int,
    absent_count int,
    leave_count int,
    percentage numeric(5,2),
    status_band text,
    met_minimum boolean,
    is_current boolean
) AS $$
DECLARE
    v_batch_id bigint;
    v_curr_sem int;
    r RECORD;
    v_sum RECORD;
BEGIN
    SELECT b.id, b.current_semester INTO v_batch_id, v_curr_sem
    FROM students s
    JOIN batches b ON b.id = s.batch_id
    WHERE s.id = p_student_id;

    IF v_batch_id IS NULL THEN RETURN; END IF;

    FOR r IN (
        SELECT bs.semester_no, bs.start_date, bs.end_date, bs.status
        FROM batch_semesters bs
        WHERE bs.batch_id = v_batch_id
        ORDER BY bs.semester_no ASC
    ) LOOP
        SELECT * INTO v_sum 
        FROM student_attendance_summary(p_student_id, p_enrollment_id, r.semester_no);

        semester_no := r.semester_no;
        year_no := ceil(r.semester_no::numeric / 2.0)::int;
        start_date := r.start_date;
        end_date := r.end_date;
        status := r.status;
        sessions_held := coalesce(v_sum.sessions_held, 0);
        present_count := coalesce(v_sum.present_count, 0);
        late_count := coalesce(v_sum.late_count, 0);
        absent_count := coalesce(v_sum.absent_count, 0);
        leave_count := coalesce(v_sum.leave_count, 0);
        percentage := coalesce(v_sum.percentage, 100.0);
        status_band := coalesce(v_sum.status_band, 'ok');
        met_minimum := (percentage >= 75.0);
        is_current := (r.semester_no = v_curr_sem);
        RETURN NEXT;
    END LOOP;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER STABLE
SET search_path = public, pg_temp;

-- =============================================================================
-- 9. evaluate_attendance_bands: Current Semester Only
-- =============================================================================
CREATE OR REPLACE FUNCTION evaluate_attendance_bands(
    p_student_id bigint DEFAULT NULL,
    p_batch_id bigint DEFAULT NULL
)
RETURNS jsonb AS $$
DECLARE
    v_target_students bigint[];
    v_sid bigint;
    v_summary RECORD;
    v_last_band text;
    v_alerts_sent int := 0;
    v_student_name text;
    v_adm_no text;
    v_enr_id bigint;
    v_admin_user_id uuid;
    v_curr_sem int;
BEGIN
    IF p_student_id IS NOT NULL THEN
        SELECT ARRAY[id] INTO v_target_students
        FROM students
        WHERE id = p_student_id AND status = 'active' AND deleted_at IS NULL;
        IF v_target_students IS NULL THEN
            RETURN jsonb_build_object('success', true, 'alerts_sent', 0, 'message', 'Student is not active.');
        END IF;
    ELSIF p_batch_id IS NOT NULL THEN
        SELECT coalesce(array_agg(s.id), ARRAY[]::bigint[])
        INTO v_target_students
        FROM students s
        JOIN student_enrollments se ON se.student_id = s.id AND se.batch_id = p_batch_id AND se.status = 'active'
        WHERE s.status = 'active' AND s.deleted_at IS NULL;
    ELSE
        RETURN jsonb_build_object('success', false, 'message', 'Either student_id or batch_id must be provided.');
    END IF;

    FOREACH v_sid IN ARRAY v_target_students
    LOOP
        -- student_attendance_summary defaults to the batch's current semester
        SELECT * INTO v_summary FROM student_attendance_summary(v_sid) LIMIT 1;

        IF v_summary.student_id IS NOT NULL THEN
            v_enr_id := coalesce(v_summary.enrollment_id, 0);
            v_curr_sem := coalesce(v_summary.semester_no, 1);

            SELECT last_band INTO v_last_band
            FROM attendance_alert_state
            WHERE student_id = v_sid AND enrollment_id = v_enr_id AND semester_no = v_curr_sem;

            IF v_last_band IS NULL THEN
                v_last_band := 'ok';
            END IF;

            IF v_summary.status_band != v_last_band THEN
                SELECT name, admission_number INTO v_student_name, v_adm_no
                FROM students WHERE id = v_sid;

                IF v_summary.status_band = 'low' THEN
                    INSERT INTO notifications (
                        recipient_type, recipient_id, type, title, body, created_at
                    ) VALUES (
                        'student', v_sid, 'attendance_warning', 'Low attendance',
                        format('Your Semester %s attendance is currently %s%%. You can miss at most %s more session(s) before facing a shortage below 75%%.', 
                               v_curr_sem, v_summary.percentage, v_summary.can_miss_more),
                        clock_timestamp()
                    );
                    v_alerts_sent := v_alerts_sent + 1;

                ELSIF v_summary.status_band = 'shortage' THEN
                    INSERT INTO notifications (
                        recipient_type, recipient_id, type, title, body, created_at
                    ) VALUES (
                        'student', v_sid, 'attendance_shortage', 'Attendance shortage',
                        format('Your Semester %s attendance is currently %s%% (below 75%%). You must attend the next %s consecutive session(s) to regain eligibility.', 
                               v_curr_sem, v_summary.percentage, v_summary.recover_sessions),
                        clock_timestamp()
                    );

                    SELECT user_id INTO v_admin_user_id FROM profiles WHERE role = 'admin' AND active = true LIMIT 1;
                    IF v_admin_user_id IS NOT NULL THEN
                        INSERT INTO notifications (
                            user_id, recipient_type, recipient_id, type, title, body, created_at
                        ) VALUES (
                            v_admin_user_id, 'admin', NULL, 'student_attendance_shortage',
                            format('Attendance shortage: %s', v_student_name),
                            format('%s (%s) has an attendance shortage of %s%% in Semester %s.', v_student_name, v_adm_no, v_summary.percentage, v_curr_sem),
                            clock_timestamp()
                        );
                    END IF;
                    v_alerts_sent := v_alerts_sent + 1;
                END IF;

                INSERT INTO attendance_alert_state (
                    student_id, enrollment_id, semester_no, last_band, updated_at
                ) VALUES (
                    v_sid, v_enr_id, v_curr_sem, v_summary.status_band, clock_timestamp()
                )
                ON CONFLICT (student_id, enrollment_id, semester_no)
                DO UPDATE SET
                    last_band = EXCLUDED.last_band,
                    updated_at = EXCLUDED.updated_at;
            END IF;
        END IF;
    END LOOP;

    RETURN jsonb_build_object('success', true, 'alerts_sent', v_alerts_sent);
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- =============================================================================
-- 10. preview_semester_promotion(batch_id) & promote_semester(...)
-- =============================================================================
CREATE OR REPLACE FUNCTION preview_semester_promotion(p_batch_id bigint)
RETURNS jsonb AS $$
DECLARE
    v_b RECORD;
    v_dur_years int;
    v_max_sem int;
    v_students jsonb;
    v_below_count int := 0;
    v_total_count int := 0;
BEGIN
    SELECT b.*, c.name AS course_name, c.id AS c_id
    INTO v_b
    FROM batches b
    JOIN courses c ON c.id = b.course_id
    WHERE b.id = p_batch_id AND b.deleted_at IS NULL;

    IF v_b.id IS NULL THEN
        RAISE EXCEPTION 'Batch % not found.', p_batch_id;
    END IF;

    v_dur_years := course_duration_years(v_b.c_id);
    v_max_sem := v_dur_years * 2;

    WITH batch_studs AS (
        SELECT s.id, s.name, s.admission_number, s.registration_number, se.id AS enr_id
        FROM students s
        JOIN student_enrollments se ON se.student_id = s.id AND se.batch_id = p_batch_id AND se.status = 'active'
        WHERE s.status = 'active' AND s.deleted_at IS NULL
    ),
    stud_summaries AS (
        SELECT 
            bs.id AS student_id,
            bs.name,
            bs.admission_number,
            bs.registration_number,
            coalesce(att.sessions_held, 0) AS sessions_held,
            coalesce(att.present_count + att.late_count, 0) AS attended_count,
            coalesce(att.percentage, 100.0) AS attendance_percentage,
            coalesce(att.status_band, 'ok') AS status_band,
            (coalesce(att.percentage, 100.0) < 75.0) AS below_minimum
        FROM batch_studs bs
        LEFT JOIN LATERAL (
            SELECT sas.* FROM student_attendance_summary(bs.id, bs.enr_id, v_b.current_semester) sas
            LIMIT 1
        ) att ON true
    )
    SELECT 
        coalesce(jsonb_agg(to_jsonb(ss)), '[]'::jsonb),
        count(*)::int,
        count(*) FILTER (WHERE ss.below_minimum)::int
    INTO v_students, v_total_count, v_below_count
    FROM stud_summaries ss;

    RETURN jsonb_build_object(
        'batch_id', v_b.id,
        'batch_name', v_b.batch_name,
        'course_name', v_b.course_name,
        'current_semester', v_b.current_semester,
        'current_year', ceil(v_b.current_semester::numeric / 2.0)::int,
        'next_semester', v_b.current_semester + 1,
        'next_year', ceil((v_b.current_semester + 1)::numeric / 2.0)::int,
        'year_will_change', (ceil((v_b.current_semester + 1)::numeric / 2.0)::int > ceil(v_b.current_semester::numeric / 2.0)::int),
        'course_duration_years', v_dur_years,
        'max_semesters', v_max_sem,
        'is_final_semester', (v_b.current_semester >= v_max_sem),
        'total_students', v_total_count,
        'below_minimum_count', v_below_count,
        'students', v_students
    );
END;
$$ LANGUAGE plpgsql SECURITY DEFINER STABLE;

CREATE OR REPLACE FUNCTION promote_semester(
    p_batch_id bigint,
    p_closing_end_date date,
    p_new_start_date date
)
RETURNS jsonb AS $$
DECLARE
    v_b RECORD;
    v_dur_years int;
    v_max_sem int;
    v_curr_sem int;
    v_next_sem int;
    v_next_year int;
    v_prev_sem_start date;
    v_s RECORD;
    v_att RECORD;
    v_promoted_count int := 0;
BEGIN
    -- Admin guard
    IF NOT EXISTS (
        SELECT 1 FROM profiles 
        WHERE profiles.id = auth.uid() AND profiles.role = 'admin' AND profiles.active = true
    ) THEN
        RAISE EXCEPTION 'Access denied. Only administrators can execute semester promotions.';
    END IF;

    SELECT b.*, c.id AS c_id, c.name AS course_name
    INTO v_b
    FROM batches b
    JOIN courses c ON c.id = b.course_id
    WHERE b.id = p_batch_id AND b.deleted_at IS NULL;

    IF v_b.id IS NULL THEN
        RAISE EXCEPTION 'Batch % not found.', p_batch_id;
    END IF;

    v_dur_years := course_duration_years(v_b.c_id);
    v_max_sem := v_dur_years * 2;
    v_curr_sem := v_b.current_semester;
    v_next_sem := v_curr_sem + 1;
    v_next_year := ceil(v_next_sem::numeric / 2.0)::int;

    IF v_curr_sem >= v_max_sem THEN
        RAISE EXCEPTION 'Batch "%" is already in its final semester (Semester %). Use "Mark batch completed" instead of promotion.',
            v_b.batch_name, v_curr_sem;
    END IF;

    -- Validate dates
    SELECT start_date INTO v_prev_sem_start 
    FROM batch_semesters 
    WHERE batch_id = p_batch_id AND semester_no = v_curr_sem;

    IF v_prev_sem_start IS NOT NULL AND p_closing_end_date < v_prev_sem_start THEN
        RAISE EXCEPTION 'Closing semester end date (%) cannot be earlier than its start date (%).',
            p_closing_end_date, v_prev_sem_start;
    END IF;

    IF p_new_start_date <= p_closing_end_date THEN
        RAISE EXCEPTION 'New semester start date (%) must be after closing semester end date (%).',
            p_new_start_date, p_closing_end_date;
    END IF;

    -- 1. Close current semester
    UPDATE batch_semesters
    SET end_date = p_closing_end_date,
        status = 'closed',
        updated_at = clock_timestamp()
    WHERE batch_id = p_batch_id AND semester_no = v_curr_sem;

    -- 2. Open next semester
    INSERT INTO batch_semesters (batch_id, semester_no, start_date, end_date, status)
    VALUES (p_batch_id, v_next_sem, p_new_start_date, NULL, 'active');

    -- 3. Advance batch current_semester
    UPDATE batches
    SET current_semester = v_next_sem,
        updated_at = clock_timestamp()
    WHERE id = p_batch_id;

    -- 4. Audit log
    INSERT INTO audit_log (table_name, record_id, action, old_data, new_data, actor, created_at)
    VALUES (
        'batches',
        p_batch_id::text,
        'SEMESTER_PROMOTION',
        jsonb_build_object('semester_no', v_curr_sem, 'end_date', p_closing_end_date),
        jsonb_build_object('semester_no', v_next_sem, 'start_date', p_new_start_date, 'year', v_next_year),
        auth.uid(),
        clock_timestamp()
    );

    -- 5. Notify each student of this batch with their closing attendance
    FOR v_s IN (
        SELECT s.id, s.name, se.id AS enr_id
        FROM students s
        JOIN student_enrollments se ON se.student_id = s.id AND se.batch_id = p_batch_id AND se.status = 'active'
        WHERE s.status = 'active' AND s.deleted_at IS NULL
    ) LOOP
        SELECT * INTO v_att FROM student_attendance_summary(v_s.id, v_s.enr_id, v_curr_sem);

        INSERT INTO notifications (
            recipient_type, recipient_id, type, title, body, created_at
        ) VALUES (
            'student',
            v_s.id,
            'semester_promotion',
            'Semester Promotion',
            format('You are now in Semester %s (Year %s). Your Semester %s attendance: %s%%.',
                   v_next_sem, v_next_year, v_curr_sem, coalesce(v_att.percentage, 100.0)),
            clock_timestamp()
        );
        v_promoted_count := v_promoted_count + 1;
    END LOOP;

    -- 6. Insert teacher announcement / notice
    INSERT INTO announcements (
        category, title, body, audience_type, audience_ids, created_by, created_at
    ) VALUES (
        'academic',
        format('Batch %s Promoted to Semester %s', v_b.batch_name, v_next_sem),
        format('Batch %s has successfully completed Semester %s and has advanced to Semester %s (Year %s).',
               v_b.batch_name, v_curr_sem, v_next_sem, v_next_year),
        'teachers',
        '[]'::jsonb,
        auth.uid(),
        clock_timestamp()
    );

    RETURN jsonb_build_object(
        'success', true,
        'batch_id', p_batch_id,
        'promoted_to_semester', v_next_sem,
        'promoted_to_year', v_next_year,
        'students_notified', v_promoted_count
    );
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- =============================================================================
-- 11. Admin function: Edit Semester Dates with Audit Log & Session Validation
-- =============================================================================
CREATE OR REPLACE FUNCTION admin_update_batch_semester_dates(
    p_batch_id bigint,
    p_semester_no int,
    p_start_date date,
    p_end_date date,
    p_reason text
)
RETURNS jsonb AS $$
DECLARE
    v_old RECORD;
    v_sessions_outside int := 0;
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM profiles 
        WHERE profiles.id = auth.uid() AND profiles.role = 'admin' AND profiles.active = true
    ) THEN
        RAISE EXCEPTION 'Access denied. Only administrators can modify semester dates.';
    END IF;

    IF p_end_date IS NOT NULL AND p_end_date < p_start_date THEN
        RAISE EXCEPTION 'End date (%) cannot be earlier than start date (%).', p_end_date, p_start_date;
    END IF;

    SELECT * INTO v_old FROM batch_semesters 
    WHERE batch_id = p_batch_id AND semester_no = p_semester_no;

    IF v_old.id IS NULL THEN
        RAISE EXCEPTION 'Semester % for batch % does not exist.', p_semester_no, p_batch_id;
    END IF;

    -- Check if existing attendance sessions fall outside the new date boundaries
    SELECT count(*)::int INTO v_sessions_outside
    FROM attendance_sessions
    WHERE batch_id = p_batch_id 
      AND semester_no = p_semester_no
      AND (date < p_start_date OR (p_end_date IS NOT NULL AND date > p_end_date));

    IF v_sessions_outside > 0 AND (p_reason IS NULL OR trim(p_reason) = '') THEN
        RAISE EXCEPTION 'There are % attendance sessions falling outside the updated date range. A mandatory explanation reason is required.',
            v_sessions_outside;
    END IF;

    UPDATE batch_semesters
    SET start_date = p_start_date,
        end_date = p_end_date,
        updated_at = clock_timestamp()
    WHERE id = v_old.id;

    INSERT INTO audit_log (table_name, record_id, action, old_data, new_data, actor, created_at)
    VALUES (
        'batch_semesters',
        v_old.id::text,
        'UPDATE_SEMESTER_DATES',
        to_jsonb(v_old),
        jsonb_build_object('start_date', p_start_date, 'end_date', p_end_date, 'reason', p_reason),
        auth.uid(),
        clock_timestamp()
    );

    RETURN jsonb_build_object('success', true, 'affected_sessions', v_sessions_outside);
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- =============================================================================
-- 12. Admin function: Modify Session Semester with Audit Log
-- =============================================================================
CREATE OR REPLACE FUNCTION admin_update_session_semester(
    p_session_id bigint,
    p_new_semester_no int,
    p_reason text
)
RETURNS jsonb AS $$
DECLARE
    v_s RECORD;
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM profiles 
        WHERE profiles.id = auth.uid() AND profiles.role = 'admin' AND profiles.active = true
    ) THEN
        RAISE EXCEPTION 'Access denied. Only administrators can alter session semester mappings.';
    END IF;

    IF p_reason IS NULL OR trim(p_reason) = '' THEN
        RAISE EXCEPTION 'A valid explanation reason is mandatory for altering session semester assignments.';
    END IF;

    SELECT * INTO v_s FROM attendance_sessions WHERE id = p_session_id;
    IF v_s.id IS NULL THEN
        RAISE EXCEPTION 'Session % not found.', p_session_id;
    END IF;

    UPDATE attendance_sessions
    SET semester_no = p_new_semester_no
    WHERE id = p_session_id;

    INSERT INTO audit_log (table_name, record_id, action, old_data, new_data, actor, created_at)
    VALUES (
        'attendance_sessions',
        p_session_id::text,
        'UPDATE_SESSION_SEMESTER',
        jsonb_build_object('old_semester', v_s.semester_no),
        jsonb_build_object('new_semester', p_new_semester_no, 'reason', p_reason),
        auth.uid(),
        clock_timestamp()
    );

    RETURN jsonb_build_object('success', true, 'session_id', p_session_id, 'new_semester', p_new_semester_no);
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- =============================================================================
-- 13. Reports and Views with Semester Parameter
-- =============================================================================
CREATE OR REPLACE FUNCTION report_shortage(
    p_course_id bigint DEFAULT NULL,
    p_batch_id bigint DEFAULT NULL,
    p_semester_no int DEFAULT NULL,
    p_band text DEFAULT 'all'
)
RETURNS TABLE (
    student_id bigint,
    student_name text,
    admission_number text,
    registration_number text,
    course_name text,
    batch_name text,
    course_id bigint,
    batch_id bigint,
    semester_no int,
    year_no int,
    sessions_held int,
    present_count int,
    late_count int,
    absent_count int,
    leave_count int,
    percentage numeric(5,2),
    status_band text,
    can_miss_more int,
    recover_sessions int
) AS $$
BEGIN
    RETURN QUERY
    WITH active_studs AS (
        SELECT 
            s.id AS sid,
            s.name AS sname,
            s.admission_number AS sadm,
            s.registration_number AS sreg,
            c.name AS cname,
            b.batch_name AS bname,
            s.course_id AS cid,
            s.batch_id AS bid,
            b.current_semester AS b_curr_sem,
            se.id AS eid
        FROM students s
        JOIN courses c ON c.id = s.course_id
        JOIN batches b ON b.id = s.batch_id
        JOIN student_enrollments se ON se.student_id = s.id AND se.batch_id = b.id AND se.status = 'active'
        WHERE s.status = 'active'
          AND s.deleted_at IS NULL
          AND (p_course_id IS NULL OR s.course_id = p_course_id)
          AND (p_batch_id IS NULL OR s.batch_id = p_batch_id)
    )
    SELECT 
        ast.sid,
        ast.sname,
        ast.sadm,
        ast.sreg,
        ast.cname,
        ast.bname,
        ast.cid,
        ast.bid,
        coalesce(p_semester_no, ast.b_curr_sem) AS semester_no,
        ceil(coalesce(p_semester_no, ast.b_curr_sem)::numeric / 2.0)::int AS year_no,
        coalesce(att.sessions_held, 0),
        coalesce(att.present_count, 0),
        coalesce(att.late_count, 0),
        coalesce(att.absent_count, 0),
        coalesce(att.leave_count, 0),
        coalesce(att.percentage, 100.0),
        coalesce(att.status_band, 'ok'),
        coalesce(att.can_miss_more, 0),
        coalesce(att.recover_sessions, 0)
    FROM active_studs ast
    LEFT JOIN LATERAL (
        SELECT sas.* FROM student_attendance_summary(ast.sid, ast.eid, coalesce(p_semester_no, ast.b_curr_sem)) sas
        LIMIT 1
    ) att ON true
    WHERE p_band = 'all' OR coalesce(att.status_band, 'ok') = p_band;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER STABLE;

