-- >>> START OF supabase/migrations\0020_unified_course_structure_and_year_system.sql <<<

-- =============================================================================
-- Migration 0020: Unified Course Structure, Year-wise System & Period Generalization
-- Phases 13 & 14 Unified Architecture
-- =============================================================================

-- -----------------------------------------------------------------------------
-- 1. COURSES: Structure & Attendance Basis
-- -----------------------------------------------------------------------------

-- Add structure: 'semester' (default), 'year', 'single'
ALTER TABLE courses
    ADD COLUMN IF NOT EXISTS structure text NOT NULL DEFAULT 'semester' 
    CHECK (structure IN ('semester', 'year', 'single'));

-- Add attendance_basis: 'semester' (default), 'year', 'none'
ALTER TABLE courses
    ADD COLUMN IF NOT EXISTS attendance_basis text NOT NULL DEFAULT 'semester' 
    CHECK (attendance_basis IN ('semester', 'year', 'none'));

-- Data migration: skill courses become 'single' with 'none' attendance; others become 'semester'
UPDATE courses
SET structure = CASE 
        WHEN course_type = 'skill' THEN 'single'
        ELSE 'semester'
    END,
    attendance_basis = CASE 
        WHEN course_type = 'skill' THEN 'none'
        ELSE 'semester'
    END
WHERE structure IS NULL OR structure = 'semester';

-- Helper: total period count for a course
CREATE OR REPLACE FUNCTION course_periods_count(p_course_id bigint)
RETURNS int AS $$
DECLARE
    v_structure text;
    v_dur_years int;
BEGIN
    SELECT structure INTO v_structure FROM courses WHERE id = p_course_id;
    IF v_structure IS NULL THEN RETURN 4; END IF;
    
    IF v_structure = 'single' THEN
        RETURN 1;
    END IF;

    v_dur_years := course_duration_years(p_course_id);
    IF v_structure = 'year' THEN
        RETURN GREATEST(1, v_dur_years);
    ELSE
        -- semester-wise: years * 2
        RETURN GREATEST(1, v_dur_years * 2);
    END IF;
END;
$$ LANGUAGE plpgsql STABLE;

-- Trigger: Course structure cannot be changed once exams, marks or attendance sessions exist
CREATE OR REPLACE FUNCTION check_course_structure_locked()
RETURNS TRIGGER AS $$
BEGIN
    IF OLD.structure IS DISTINCT FROM NEW.structure THEN
        -- Check exams
        IF EXISTS (SELECT 1 FROM exams WHERE course_id = NEW.id AND deleted_at IS NULL) THEN
            RAISE EXCEPTION 'Cannot alter structure for course "%" (ID %). Course structure is locked because exams already exist.',
                NEW.name, NEW.id;
        END IF;

        -- Check attendance sessions
        IF EXISTS (
            SELECT 1 FROM attendance_sessions s
            JOIN batches b ON b.id = s.batch_id
            WHERE b.course_id = NEW.id
        ) THEN
            RAISE EXCEPTION 'Cannot alter structure for course "%" (ID %). Course structure is locked because attendance sessions already exist.',
                NEW.name, NEW.id;
        END IF;
    END IF;

    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS trg_check_course_structure_locked ON courses;
CREATE TRIGGER trg_check_course_structure_locked
    BEFORE UPDATE OF structure ON courses
    FOR EACH ROW EXECUTE FUNCTION check_course_structure_locked();


-- -----------------------------------------------------------------------------
-- 2. GENERALIZE BATCH SEMESTERS -> BATCH PERIODS
-- -----------------------------------------------------------------------------

-- Drop dependent view if exists from earlier attempts
DROP VIEW IF EXISTS batch_semesters CASCADE;

DO $$
BEGIN
    IF EXISTS (
        SELECT 1 FROM information_schema.tables 
        WHERE table_schema = 'public' AND table_name = 'batch_semesters'
    ) THEN
        -- Rename table
        ALTER TABLE batch_semesters RENAME TO batch_periods;

        -- Rename semester_no column to period_no if needed
        IF EXISTS (
            SELECT 1 FROM information_schema.columns 
            WHERE table_schema = 'public' AND table_name = 'batch_periods' AND column_name = 'semester_no'
        ) THEN
            ALTER TABLE batch_periods RENAME COLUMN semester_no TO period_no;
        END IF;
    END IF;
END $$;

-- Ensure batch_periods table exists
CREATE TABLE IF NOT EXISTS batch_periods (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    batch_id bigint NOT NULL REFERENCES batches(id) ON DELETE CASCADE,
    period_type text NOT NULL DEFAULT 'semester' CHECK (period_type IN ('semester', 'year')),
    period_no int NOT NULL CHECK (period_no >= 1),
    start_date date NOT NULL,
    end_date date,
    status text NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'closed')),
    created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
    updated_at timestamptz NOT NULL DEFAULT clock_timestamp(),
    CONSTRAINT chk_period_dates CHECK (end_date IS NULL OR end_date >= start_date)
);

-- Ensure period_type column exists
ALTER TABLE batch_periods
    ADD COLUMN IF NOT EXISTS period_type text NOT NULL DEFAULT 'semester' CHECK (period_type IN ('semester', 'year'));

-- Update unique constraint to (batch_id, period_type, period_no)
ALTER TABLE batch_periods DROP CONSTRAINT IF EXISTS uk_batch_semester;
ALTER TABLE batch_periods DROP CONSTRAINT IF EXISTS uk_batch_period;
ALTER TABLE batch_periods ADD CONSTRAINT uk_batch_period UNIQUE (batch_id, period_type, period_no);

CREATE INDEX IF NOT EXISTS idx_batch_periods_lookup 
    ON batch_periods (batch_id, period_type, period_no, status);

-- Trigger: Non-overlapping periods per batch and period_type
CREATE OR REPLACE FUNCTION check_batch_period_non_overlapping()
RETURNS TRIGGER AS $$
BEGIN
    IF EXISTS (
        SELECT 1 FROM batch_periods
        WHERE batch_id = NEW.batch_id
          AND period_type = NEW.period_type
          AND id != coalesce(NEW.id, -1)
          AND daterange(start_date, coalesce(end_date, '9999-12-31'::date), '[]') &&
              daterange(NEW.start_date, coalesce(NEW.end_date, '9999-12-31'::date), '[]')
    ) THEN
        RAISE EXCEPTION '% date range [% to %] overlaps with an existing % for batch %.',
            initcap(NEW.period_type), NEW.start_date, coalesce(NEW.end_date::text, 'ongoing'), NEW.period_type, NEW.batch_id;
    END IF;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS trg_check_batch_period_dates ON batch_periods;
CREATE TRIGGER trg_check_batch_period_dates
    BEFORE INSERT OR UPDATE OF start_date, end_date ON batch_periods
    FOR EACH ROW EXECUTE FUNCTION check_batch_period_non_overlapping();

ALTER TABLE batch_periods ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS p_batch_periods_all ON batch_periods;
CREATE POLICY p_batch_periods_all ON batch_periods
    FOR ALL TO authenticated
    USING (true)
    WITH CHECK (
        EXISTS (
            SELECT 1 FROM profiles 
            WHERE profiles.id = auth.uid() AND profiles.role = 'admin' AND profiles.active = true
        )
    );

-- Backward-compatible temporary view with security_invoker = true
CREATE OR REPLACE VIEW batch_semesters
WITH (security_invoker = true) AS
SELECT 
    id,
    batch_id,
    period_no AS semester_no,
    start_date,
    end_date,
    status,
    created_at,
    updated_at
FROM batch_periods
WHERE period_type = 'semester';

-- INSTEAD OF trigger on batch_semesters view for backward-compatible writes
CREATE OR REPLACE FUNCTION trg_batch_semesters_compat_io()
RETURNS TRIGGER AS $$
BEGIN
    IF TG_OP = 'INSERT' THEN
        INSERT INTO batch_periods (batch_id, period_type, period_no, start_date, end_date, status)
        VALUES (NEW.batch_id, 'semester', NEW.semester_no, NEW.start_date, NEW.end_date, coalesce(NEW.status, 'active'))
        RETURNING id INTO NEW.id;
        RETURN NEW;
    ELSIF TG_OP = 'UPDATE' THEN
        UPDATE batch_periods
        SET start_date = NEW.start_date,
            end_date = NEW.end_date,
            status = NEW.status,
            period_no = NEW.semester_no,
            updated_at = clock_timestamp()
        WHERE id = OLD.id;
        RETURN NEW;
    ELSIF TG_OP = 'DELETE' THEN
        DELETE FROM batch_periods WHERE id = OLD.id;
        RETURN OLD;
    END IF;
    RETURN NULL;
END;
$$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS trg_batch_semesters_io ON batch_semesters;
CREATE TRIGGER trg_batch_semesters_io
    INSTEAD OF INSERT OR UPDATE OR DELETE ON batch_semesters
    FOR EACH ROW EXECUTE FUNCTION trg_batch_semesters_compat_io();


-- -----------------------------------------------------------------------------
-- 3. BATCHES: Synchronize current_semester & current_year Derivation
-- -----------------------------------------------------------------------------

-- Drop generated column restriction on current_year so it supports both semester and year workflows
DO $$
BEGIN
    IF EXISTS (
        SELECT 1 FROM information_schema.columns 
        WHERE table_schema = 'public' AND table_name = 'batches' 
          AND column_name = 'current_year' AND is_generated = 'ALWAYS'
    ) THEN
        ALTER TABLE batches DROP COLUMN current_year;
        ALTER TABLE batches ADD COLUMN current_year int NOT NULL DEFAULT 1 CHECK (current_year >= 1);
    END IF;
END $$;

ALTER TABLE batches
    ADD COLUMN IF NOT EXISTS current_year int NOT NULL DEFAULT 1 CHECK (current_year >= 1);

-- Trigger to keep current_semester and current_year synchronized based on course structure
CREATE OR REPLACE FUNCTION sync_batch_periods()
RETURNS TRIGGER AS $$
DECLARE
    v_structure text;
BEGIN
    SELECT structure INTO v_structure FROM courses WHERE id = NEW.course_id;
    
    IF v_structure = 'year' THEN
        -- For year-wise courses: current_year is primary
        NEW.current_year := coalesce(NEW.current_year, 1);
        NEW.current_semester := NEW.current_year * 2;
    ELSE
        -- For semester-wise courses (default): current_semester is primary
        NEW.current_semester := coalesce(NEW.current_semester, 1);
        NEW.current_year := ceil(NEW.current_semester::numeric / 2.0)::int;
    END IF;

    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS trg_sync_batch_periods ON batches;
CREATE TRIGGER trg_sync_batch_periods
    BEFORE INSERT OR UPDATE OF current_semester, current_year, course_id ON batches
    FOR EACH ROW EXECUTE FUNCTION sync_batch_periods();

-- Sync existing batches
UPDATE batches SET current_semester = current_semester;


-- -----------------------------------------------------------------------------
-- 4. COURSE SUBJECTS: Add period_no Semantics
-- -----------------------------------------------------------------------------

ALTER TABLE course_subjects
    ADD COLUMN IF NOT EXISTS period_no int CHECK (period_no IS NULL OR period_no >= 1);

CREATE INDEX IF NOT EXISTS idx_course_subjects_period 
    ON course_subjects (course_id, period_no) WHERE deleted_at IS NULL;


-- -----------------------------------------------------------------------------
-- 5. EXAMS: Add period_type, period_no & override_reason
-- -----------------------------------------------------------------------------

ALTER TABLE exams
    ADD COLUMN IF NOT EXISTS period_type text CHECK (period_type IS NULL OR period_type IN ('semester', 'year')),
    ADD COLUMN IF NOT EXISTS period_no int CHECK (period_no IS NULL OR period_no >= 1),
    ADD COLUMN IF NOT EXISTS override_reason text;

CREATE INDEX IF NOT EXISTS idx_exams_period 
    ON exams (course_id, batch_id, period_type, period_no) WHERE deleted_at IS NULL;

-- Convert legacy exams.semester text into period_no and period_type
UPDATE exams
SET period_type = 'semester',
    period_no = CASE
        -- Direct digits '1', '2', etc.
        WHEN trim(semester) ~ '^[0-9]+$' THEN trim(semester)::int
        -- Words: Semester 1, Sem 2, S1
        WHEN trim(semester) ~* '^(sem(ester)?|s)[\s\-_]*1$' THEN 1
        WHEN trim(semester) ~* '^(sem(ester)?|s)[\s\-_]*2$' THEN 2
        WHEN trim(semester) ~* '^(sem(ester)?|s)[\s\-_]*3$' THEN 3
        WHEN trim(semester) ~* '^(sem(ester)?|s)[\s\-_]*4$' THEN 4
        WHEN trim(semester) ~* '^(sem(ester)?|s)[\s\-_]*5$' THEN 5
        WHEN trim(semester) ~* '^(sem(ester)?|s)[\s\-_]*6$' THEN 6
        WHEN trim(semester) ~* '^(sem(ester)?|s)[\s\-_]*7$' THEN 7
        WHEN trim(semester) ~* '^(sem(ester)?|s)[\s\-_]*8$' THEN 8
        -- Roman Numerals: I, II, III, IV, V, VI, VII, VIII
        WHEN trim(semester) ~* '^(sem(ester)?[\s\-_]*)?i$' THEN 1
        WHEN trim(semester) ~* '^(sem(ester)?[\s\-_]*)?ii$' THEN 2
        WHEN trim(semester) ~* '^(sem(ester)?[\s\-_]*)?iii$' THEN 3
        WHEN trim(semester) ~* '^(sem(ester)?[\s\-_]*)?iv$' THEN 4
        WHEN trim(semester) ~* '^(sem(ester)?[\s\-_]*)?v$' THEN 5
        WHEN trim(semester) ~* '^(sem(ester)?[\s\-_]*)?vi$' THEN 6
        WHEN trim(semester) ~* '^(sem(ester)?[\s\-_]*)?vii$' THEN 7
        WHEN trim(semester) ~* '^(sem(ester)?[\s\-_]*)?viii$' THEN 8
        ELSE NULL
    END
WHERE semester IS NOT NULL AND period_no IS NULL;


-- -----------------------------------------------------------------------------
-- 6. RESULTS: Carry period_type and period_no
-- -----------------------------------------------------------------------------

ALTER TABLE results
    ADD COLUMN IF NOT EXISTS period_type text CHECK (period_type IS NULL OR period_type IN ('semester', 'year')),
    ADD COLUMN IF NOT EXISTS period_no int CHECK (period_no IS NULL OR period_no >= 1);

-- Backfill results from parent exams
UPDATE results r
SET period_type = e.period_type,
    period_no = e.period_no
FROM exams e
WHERE e.id = r.exam_id
  AND (r.period_no IS NULL OR r.period_type IS NULL);


-- -----------------------------------------------------------------------------
-- 7. ATTENDANCE SESSIONS & ALERTS: Period Generalization
-- -----------------------------------------------------------------------------

ALTER TABLE attendance_sessions
    ADD COLUMN IF NOT EXISTS period_type text NOT NULL DEFAULT 'semester' CHECK (period_type IN ('semester', 'year')),
    ADD COLUMN IF NOT EXISTS period_no int;

-- Backfill existing attendance sessions
UPDATE attendance_sessions
SET period_no = semester_no,
    period_type = 'semester'
WHERE period_no IS NULL AND semester_no IS NOT NULL;

CREATE INDEX IF NOT EXISTS idx_attendance_sessions_period 
    ON attendance_sessions (batch_id, period_type, period_no);

-- Period Assignment Trigger on attendance_sessions
CREATE OR REPLACE FUNCTION assign_attendance_session_period()
RETURNS TRIGGER AS $$
DECLARE
    v_basis text;
    v_period_type text;
    v_period_no int;
BEGIN
    SELECT coalesce(c.attendance_basis, c.structure, 'semester')
    INTO v_basis
    FROM batches b
    JOIN courses c ON c.id = b.course_id
    WHERE b.id = NEW.batch_id;

    IF v_basis = 'none' THEN
        NEW.period_type := 'semester';
        NEW.period_no := NULL;
        NEW.semester_no := NULL;
        RETURN NEW;
    END IF;

    v_period_type := v_basis;

    -- 1. Date window match in batch_periods
    SELECT period_no INTO v_period_no
    FROM batch_periods
    WHERE batch_id = NEW.batch_id
      AND period_type = v_period_type
      AND start_date <= NEW.date
      AND (end_date IS NULL OR end_date >= NEW.date)
    ORDER BY period_no DESC
    LIMIT 1;

    -- 2. Active status match in batch_periods
    IF v_period_no IS NULL THEN
        SELECT period_no INTO v_period_no
        FROM batch_periods
        WHERE batch_id = NEW.batch_id
          AND period_type = v_period_type
          AND status = 'active'
        ORDER BY period_no DESC
        LIMIT 1;
    END IF;

    -- 3. Batch current period fallback
    IF v_period_no IS NULL THEN
        IF v_period_type = 'year' THEN
            SELECT current_year INTO v_period_no FROM batches WHERE id = NEW.batch_id;
        ELSE
            SELECT current_semester INTO v_period_no FROM batches WHERE id = NEW.batch_id;
        END IF;
    END IF;

    NEW.period_type := v_period_type;
    NEW.period_no := coalesce(v_period_no, 1);
    IF v_period_type = 'semester' THEN
        NEW.semester_no := NEW.period_no;
    ELSE
        NEW.semester_no := NEW.period_no * 2;
    END IF;

    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS trg_assign_attendance_semester ON attendance_sessions;
DROP TRIGGER IF EXISTS trg_assign_attendance_period ON attendance_sessions;
CREATE TRIGGER trg_assign_attendance_period
    BEFORE INSERT OR UPDATE OF date, batch_id ON attendance_sessions
    FOR EACH ROW EXECUTE FUNCTION assign_attendance_session_period();

-- Attendance alert state table: generalize to period_type & period_no
ALTER TABLE attendance_alert_state
    ADD COLUMN IF NOT EXISTS period_type text NOT NULL DEFAULT 'semester' CHECK (period_type IN ('semester', 'year')),
    ADD COLUMN IF NOT EXISTS period_no int;

UPDATE attendance_alert_state
SET period_no = semester_no
WHERE period_no IS NULL;

-- Update primary key on attendance_alert_state
DO $$
BEGIN
    ALTER TABLE attendance_alert_state DROP CONSTRAINT IF EXISTS attendance_alert_state_pkey;
    ALTER TABLE attendance_alert_state ADD PRIMARY KEY (student_id, enrollment_id, period_type, period_no);
EXCEPTION WHEN OTHERS THEN
    -- In case of existing duplicates, handle gracefully
    NULL;
END $$;


-- -----------------------------------------------------------------------------
-- 8. ATTENDANCE SUMMARY FUNCTION (PERIOD AWARE)
-- -----------------------------------------------------------------------------

CREATE OR REPLACE FUNCTION student_attendance_summary(
    p_student_id bigint,
    p_enrollment_id bigint,
    p_period_no int DEFAULT NULL,
    p_period_type text DEFAULT NULL
)
RETURNS TABLE (
    student_id bigint,
    enrollment_id bigint,
    batch_id bigint,
    period_type text,
    period_no int,
    semester_no int,
    year_no int,
    total_sessions int,
    attended_sessions int,
    late_sessions int,
    absent_sessions int,
    percentage numeric(5,2),
    band text,
    is_shortage boolean
) AS $$
DECLARE
    v_batch_id bigint;
    v_course_id bigint;
    v_att_basis text;
    v_type text;
    v_target_period int;
    v_curr_period int;
    v_period_start date;
    v_period_end date;
    v_total int := 0;
    v_present int := 0;
    v_late int := 0;
    v_absent int := 0;
    v_pct numeric(5,2) := 100.0;
    v_band text := 'green';
BEGIN
    SELECT e.batch_id, b.course_id, b.current_semester, b.current_year, coalesce(c.attendance_basis, 'semester')
    INTO v_batch_id, v_course_id, v_curr_period, v_curr_period, v_att_basis
    FROM enrollments e
    JOIN batches b ON b.id = e.batch_id
    JOIN courses c ON c.id = b.course_id
    WHERE e.id = p_enrollment_id AND e.student_id = p_student_id;

    IF NOT FOUND THEN RETURN; END IF;

    v_type := coalesce(p_period_type, v_att_basis, 'semester');
    IF v_type NOT IN ('semester', 'year') THEN v_type := 'semester'; END IF;

    IF p_period_no IS NOT NULL THEN
        v_target_period := p_period_no;
    ELSE
        IF v_type = 'year' THEN
            SELECT current_year INTO v_target_period FROM batches WHERE id = v_batch_id;
        ELSE
            SELECT current_semester INTO v_target_period FROM batches WHERE id = v_batch_id;
        END IF;
    END IF;
    v_target_period := coalesce(v_target_period, 1);

    -- Get period date window
    SELECT start_date, end_date INTO v_period_start, v_period_end
    FROM batch_periods
    WHERE batch_id = v_batch_id AND period_type = v_type AND period_no = v_target_period;

    -- Aggregate sessions
    SELECT count(DISTINCT s.id) INTO v_total
    FROM attendance_sessions s
    WHERE s.batch_id = v_batch_id
      AND s.period_type = v_type
      AND (s.period_no = v_target_period OR (v_period_start IS NOT NULL AND s.date >= v_period_start AND (v_period_end IS NULL OR s.date <= v_period_end)));

    IF v_total > 0 THEN
        -- Present count
        SELECT count(*) INTO v_present
        FROM attendance a
        JOIN attendance_sessions s ON s.id = a.session_id
        WHERE a.student_id = p_student_id
          AND s.batch_id = v_batch_id
          AND s.period_type = v_type
          AND (s.period_no = v_target_period OR (v_period_start IS NOT NULL AND s.date >= v_period_start AND (v_period_end IS NULL OR s.date <= v_period_end)))
          AND a.status = 'present';

        -- Late count
        SELECT count(*) INTO v_late
        FROM attendance a
        JOIN attendance_sessions s ON s.id = a.session_id
        WHERE a.student_id = p_student_id
          AND s.batch_id = v_batch_id
          AND s.period_type = v_type
          AND (s.period_no = v_target_period OR (v_period_start IS NOT NULL AND s.date >= v_period_start AND (v_period_end IS NULL OR s.date <= v_period_end)))
          AND a.status = 'late';

        -- Absent count
        SELECT count(*) INTO v_absent
        FROM attendance a
        JOIN attendance_sessions s ON s.id = a.session_id
        WHERE a.student_id = p_student_id
          AND s.batch_id = v_batch_id
          AND s.period_type = v_type
          AND (s.period_no = v_target_period OR (v_period_start IS NOT NULL AND s.date >= v_period_start AND (v_period_end IS NULL OR s.date <= v_period_end)))
          AND a.status = 'absent';

        -- Late weight = 0.5 present
        v_pct := round((((v_present::numeric + (v_late::numeric * 0.5)) / v_total::numeric) * 100.0), 2);
        IF v_pct > 100.0 THEN v_pct := 100.0; END IF;
    END IF;

    -- Band computation
    IF v_pct >= 80.0 THEN
        v_band := 'green';
    ELSIF v_pct >= 75.0 THEN
        v_band := 'amber';
    ELSE
        v_band := 'red';
    END IF;

    RETURN QUERY SELECT
        p_student_id,
        p_enrollment_id,
        v_batch_id,
        v_type,
        v_target_period,
        CASE WHEN v_type = 'semester' THEN v_target_period ELSE v_target_period * 2 END,
        CASE WHEN v_type = 'year' THEN v_target_period ELSE ceil(v_target_period::numeric / 2.0)::int END,
        v_total,
        v_present,
        v_late,
        v_absent,
        v_pct,
        v_band,
        (v_pct < 75.0);
END;
$$ LANGUAGE plpgsql STABLE SECURITY DEFINER;


-- -----------------------------------------------------------------------------
-- 9. YEAR-WISE PROMOTION FUNCTION: promote_year
-- -----------------------------------------------------------------------------

CREATE OR REPLACE FUNCTION preview_promote_year(
    p_batch_id bigint,
    p_closing_end_date date,
    p_new_start_date date
)
RETURNS jsonb AS $$
DECLARE
    v_b batches%ROWTYPE;
    v_c courses%ROWTYPE;
    v_active_period batch_periods%ROWTYPE;
    v_curr_year int;
    v_next_year int;
    v_max_years int;
    v_student_count int;
BEGIN
    SELECT * INTO v_b FROM batches WHERE id = p_batch_id AND deleted_at IS NULL;
    IF NOT FOUND THEN RAISE EXCEPTION 'Batch ID % does not exist.', p_batch_id; END IF;

    SELECT * INTO v_c FROM courses WHERE id = v_b.course_id;
    IF v_c.structure != 'year' THEN
        RAISE EXCEPTION 'Course "%" has structure "%". Use promote_semester for semester-wise courses.',
            v_c.name, v_c.structure;
    END IF;

    v_curr_year := v_b.current_year;
    v_next_year := v_curr_year + 1;
    v_max_years := course_duration_years(v_c.id);

    IF v_curr_year >= v_max_years THEN
        RAISE EXCEPTION 'Batch % is already in its final Year (% of %). Cannot promote further. Use complete_batch to graduate.',
            v_b.name, v_curr_year, v_max_years;
    END IF;

    IF p_closing_end_date >= p_new_start_date THEN
        RAISE EXCEPTION 'New Year start date (%) must be strictly after closing end date (%).',
            p_new_start_date, p_closing_end_date;
    END IF;

    SELECT * INTO v_active_period 
    FROM batch_periods 
    WHERE batch_id = p_batch_id AND period_type = 'year' AND period_no = v_curr_year;

    IF FOUND AND p_closing_end_date < v_active_period.start_date THEN
        RAISE EXCEPTION 'Closing end date (%) cannot be earlier than current Year start date (%).',
            p_closing_end_date, v_active_period.start_date;
    END IF;

    SELECT count(*) INTO v_student_count
    FROM enrollments
    WHERE batch_id = p_batch_id AND status = 'active';

    RETURN jsonb_build_object(
        'batch_id', p_batch_id,
        'batch_name', v_b.name,
        'course_name', v_c.name,
        'current_year', v_curr_year,
        'next_year', v_next_year,
        'max_years', v_max_years,
        'active_students_count', v_student_count,
        'closing_end_date', p_closing_end_date,
        'new_start_date', p_new_start_date
    );
END;
$$ LANGUAGE plpgsql STABLE SECURITY DEFINER;


CREATE OR REPLACE FUNCTION promote_year(
    p_batch_id bigint,
    p_closing_end_date date,
    p_new_start_date date,
    p_override_reason text DEFAULT NULL
)
RETURNS jsonb AS $$
DECLARE
    v_b batches%ROWTYPE;
    v_c courses%ROWTYPE;
    v_curr_year int;
    v_next_year int;
    v_max_years int;
    v_preview jsonb;
    v_notif_count int := 0;
BEGIN
    IF NOT is_admin() THEN
        RAISE EXCEPTION 'Access denied. Administrator privilege required to promote batches.';
    END IF;

    v_preview := preview_promote_year(p_batch_id, p_closing_end_date, p_new_start_date);
    
    SELECT * INTO v_b FROM batches WHERE id = p_batch_id;
    SELECT * INTO v_c FROM courses WHERE id = v_b.course_id;

    v_curr_year := v_b.current_year;
    v_next_year := v_curr_year + 1;
    v_max_years := course_duration_years(v_c.id);

    -- 1. Close current year in batch_periods
    UPDATE batch_periods
    SET end_date = p_closing_end_date,
        status = 'closed',
        updated_at = clock_timestamp()
    WHERE batch_id = p_batch_id AND period_type = 'year' AND period_no = v_curr_year;

    -- 2. Open new year in batch_periods
    INSERT INTO batch_periods (batch_id, period_type, period_no, start_date, end_date, status)
    VALUES (p_batch_id, 'year', v_next_year, p_new_start_date, NULL, 'active')
    ON CONFLICT (batch_id, period_type, period_no)
    DO UPDATE SET
        start_date = EXCLUDED.start_date,
        end_date = NULL,
        status = 'active',
        updated_at = clock_timestamp();

    -- 3. Update batch
    UPDATE batches
    SET current_year = v_next_year,
        current_semester = v_next_year * 2,
        updated_at = clock_timestamp()
    WHERE id = p_batch_id;

    -- 4. Audit Log
    INSERT INTO audit_logs (
        table_name, record_id, action, old_data, new_data, performed_by, reason, created_at
    ) VALUES (
        'batches',
        p_batch_id,
        'PROMOTE_YEAR',
        jsonb_build_object('year_no', v_curr_year, 'end_date', p_closing_end_date),
        jsonb_build_object('year_no', v_next_year, 'start_date', p_new_start_date),
        auth.uid(),
        coalesce(p_override_reason, 'Promoted to next academic year'),
        clock_timestamp()
    );

    -- 5. Notify active students
    INSERT INTO notifications (user_id, type, title, body, link, created_at)
    SELECT 
        p.user_id,
        'promotion',
        'Academic Year Promotion',
        'Congratulations! You have been promoted to Year ' || v_next_year || ' for ' || v_c.name || '.',
        '/attendance',
        clock_timestamp()
    FROM enrollments e
    JOIN profiles p ON p.student_id = e.student_id AND p.role = 'student' AND p.active = true
    WHERE e.batch_id = p_batch_id AND e.status = 'active';

    GET DIAGNOSTICS v_notif_count = ROW_COUNT;

    RETURN jsonb_build_object(
        'success', true,
        'batch_id', p_batch_id,
        'previous_year', v_curr_year,
        'current_year', v_next_year,
        'notified_students', v_notif_count
    );
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;


-- -----------------------------------------------------------------------------
-- 10. REVISE promote_semester: REJECT NON-SEMESTER COURSES
-- -----------------------------------------------------------------------------

CREATE OR REPLACE FUNCTION preview_promote_semester(
    p_batch_id bigint,
    p_closing_end_date date,
    p_new_start_date date
)
RETURNS jsonb AS $$
DECLARE
    v_b batches%ROWTYPE;
    v_c courses%ROWTYPE;
    v_active_sem batch_periods%ROWTYPE;
    v_curr_sem int;
    v_next_sem int;
    v_max_sems int;
    v_student_count int;
BEGIN
    SELECT * INTO v_b FROM batches WHERE id = p_batch_id AND deleted_at IS NULL;
    IF NOT FOUND THEN RAISE EXCEPTION 'Batch ID % does not exist.', p_batch_id; END IF;

    SELECT * INTO v_c FROM courses WHERE id = v_b.course_id;
    IF v_c.structure != 'semester' THEN
        RAISE EXCEPTION 'Course "%" has structure "%". Use promote_year for year-wise courses.',
            v_c.name, v_c.structure;
    END IF;

    v_curr_sem := v_b.current_semester;
    v_next_sem := v_curr_sem + 1;
    v_max_sems := course_duration_years(v_c.id) * 2;

    IF v_curr_sem >= v_max_sems THEN
        RAISE EXCEPTION 'Batch % is already in its final Semester (% of %). Cannot promote further. Use complete_batch to graduate.',
            v_b.name, v_curr_sem, v_max_sems;
    END IF;

    IF p_closing_end_date >= p_new_start_date THEN
        RAISE EXCEPTION 'New semester start date (%) must be strictly after closing end date (%).',
            p_new_start_date, p_closing_end_date;
    END IF;

    SELECT * INTO v_active_sem 
    FROM batch_periods 
    WHERE batch_id = p_batch_id AND period_type = 'semester' AND period_no = v_curr_sem;

    IF FOUND AND p_closing_end_date < v_active_sem.start_date THEN
        RAISE EXCEPTION 'Closing end date (%) cannot be earlier than current semester start date (%).',
            p_closing_end_date, v_active_sem.start_date;
    END IF;

    SELECT count(*) INTO v_student_count
    FROM enrollments
    WHERE batch_id = p_batch_id AND status = 'active';

    RETURN jsonb_build_object(
        'batch_id', p_batch_id,
        'batch_name', v_b.name,
        'course_name', v_c.name,
        'current_semester', v_curr_sem,
        'next_semester', v_next_sem,
        'max_semesters', v_max_sems,
        'active_students_count', v_student_count,
        'closing_end_date', p_closing_end_date,
        'new_start_date', p_new_start_date
    );
END;
$$ LANGUAGE plpgsql STABLE SECURITY DEFINER;


CREATE OR REPLACE FUNCTION promote_semester(
    p_batch_id bigint,
    p_closing_end_date date,
    p_new_start_date date,
    p_override_reason text DEFAULT NULL
)
RETURNS jsonb AS $$
DECLARE
    v_b batches%ROWTYPE;
    v_c courses%ROWTYPE;
    v_curr_sem int;
    v_next_sem int;
    v_next_year int;
    v_max_sems int;
    v_preview jsonb;
    v_notif_count int := 0;
BEGIN
    IF NOT is_admin() THEN
        RAISE EXCEPTION 'Access denied. Administrator privilege required to promote batches.';
    END IF;

    v_preview := preview_promote_semester(p_batch_id, p_closing_end_date, p_new_start_date);
    
    SELECT * INTO v_b FROM batches WHERE id = p_batch_id;
    SELECT * INTO v_c FROM courses WHERE id = v_b.course_id;

    v_curr_sem := v_b.current_semester;
    v_next_sem := v_curr_sem + 1;
    v_next_year := ceil(v_next_sem::numeric / 2.0)::int;
    v_max_sems := course_duration_years(v_c.id) * 2;

    -- 1. Close current semester in batch_periods
    UPDATE batch_periods
    SET end_date = p_closing_end_date,
        status = 'closed',
        updated_at = clock_timestamp()
    WHERE batch_id = p_batch_id AND period_type = 'semester' AND period_no = v_curr_sem;

    -- 2. Open new semester in batch_periods
    INSERT INTO batch_periods (batch_id, period_type, period_no, start_date, end_date, status)
    VALUES (p_batch_id, 'semester', v_next_sem, p_new_start_date, NULL, 'active')
    ON CONFLICT (batch_id, period_type, period_no)
    DO UPDATE SET
        start_date = EXCLUDED.start_date,
        end_date = NULL,
        status = 'active',
        updated_at = clock_timestamp();

    -- 3. Update batch
    UPDATE batches
    SET current_semester = v_next_sem,
        current_year = v_next_year,
        updated_at = clock_timestamp()
    WHERE id = p_batch_id;

    -- 4. Audit Log
    INSERT INTO audit_logs (
        table_name, record_id, action, old_data, new_data, performed_by, reason, created_at
    ) VALUES (
        'batches',
        p_batch_id,
        'PROMOTE_SEMESTER',
        jsonb_build_object('semester_no', v_curr_sem, 'end_date', p_closing_end_date),
        jsonb_build_object('semester_no', v_next_sem, 'start_date', p_new_start_date, 'year', v_next_year),
        auth.uid(),
        coalesce(p_override_reason, 'Promoted to next semester'),
        clock_timestamp()
    );

    -- 5. Notify active students
    INSERT INTO notifications (user_id, type, title, body, link, created_at)
    SELECT 
        p.user_id,
        'promotion',
        'Semester Promotion',
        'Congratulations! You have been promoted to Semester ' || v_next_sem || ' (Year ' || v_next_year || ') for ' || v_c.name || '.',
        '/attendance',
        clock_timestamp()
    FROM enrollments e
    JOIN profiles p ON p.student_id = e.student_id AND p.role = 'student' AND p.active = true
    WHERE e.batch_id = p_batch_id AND e.status = 'active';

    GET DIAGNOSTICS v_notif_count = ROW_COUNT;

    RETURN jsonb_build_object(
        'success', true,
        'batch_id', p_batch_id,
        'previous_semester', v_curr_sem,
        'current_semester', v_next_sem,
        'current_year', v_next_year,
        'notified_students', v_notif_count
    );
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;


-- -----------------------------------------------------------------------------
-- 11. PUBLISH EXAM: Notification Text for Semester vs Year
-- -----------------------------------------------------------------------------

CREATE OR REPLACE FUNCTION publish_exam(
    p_exam_id bigint,
    p_force_notify boolean DEFAULT false
)
RETURNS jsonb AS $$
DECLARE
    v_exam exams%ROWTYPE;
    v_was_published boolean;
    v_results_count int;
    v_notif_count int := 0;
    v_title text;
    v_body text;
BEGIN
    IF NOT is_admin() THEN
        RAISE EXCEPTION 'Access denied. Administrator privilege required to publish exams.';
    END IF;

    SELECT * INTO v_exam FROM exams WHERE id = p_exam_id AND deleted_at IS NULL;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Exam ID % does not exist.', p_exam_id;
    END IF;

    -- Ensure results have been computed first
    SELECT count(*) INTO v_results_count
    FROM results
    WHERE exam_id = p_exam_id AND deleted_at IS NULL;

    IF v_results_count = 0 THEN
        RAISE EXCEPTION 'Cannot publish exam: results have not yet been computed.';
    END IF;

    v_was_published := (v_exam.status = 'published');

    -- Update exam status
    UPDATE exams
    SET status = 'published',
        published_at = coalesce(published_at, clock_timestamp()),
        publish_date = coalesce(publish_date, CURRENT_DATE),
        updated_at = clock_timestamp()
    WHERE id = p_exam_id;

    -- Compute title & body
    IF v_exam.period_type = 'year' AND v_exam.period_no IS NOT NULL THEN
        v_title := 'Year ' || v_exam.period_no || ' Result Published';
        v_body := 'Year ' || v_exam.period_no || ' results for "' || v_exam.name || '" are now published. You can view your marksheet.';
    ELSIF v_exam.period_type = 'semester' AND v_exam.period_no IS NOT NULL THEN
        v_title := 'Semester ' || v_exam.period_no || ' Result Published';
        v_body := 'Semester ' || v_exam.period_no || ' results for "' || v_exam.name || '" are now published. You can view your marksheet.';
    ELSE
        v_title := 'Exam Results Published';
        v_body := 'Results for "' || v_exam.name || '" are now published. You can view your marksheet.';
    END IF;

    -- Dispatch notifications to students if first time or forced
    IF (NOT v_was_published) OR p_force_notify THEN
        INSERT INTO notifications (user_id, type, title, body, link, created_at)
        SELECT 
            p.user_id,
            'result_published',
            v_title,
            v_body,
            '/results/' || p_exam_id::text,
            clock_timestamp()
        FROM results r
        JOIN profiles p ON p.student_id = r.student_id AND p.role = 'student' AND p.active = true
        WHERE r.exam_id = p_exam_id AND r.deleted_at IS NULL;

        GET DIAGNOSTICS v_notif_count = ROW_COUNT;
    END IF;

    RETURN jsonb_build_object(
        'success', true,
        'exam_id', p_exam_id,
        'notifications_sent', v_notif_count
    );
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;


-- -----------------------------------------------------------------------------
-- 12. COMPUTE RESULTS: Ensure period_type and period_no are populated
-- -----------------------------------------------------------------------------

CREATE OR REPLACE FUNCTION compute_results(
    p_exam_id bigint
)
RETURNS jsonb AS $$
DECLARE
    v_exam exams%ROWTYPE;
    v_student record;
    v_mark record;
    v_total_max numeric(6,2) := 0;
    v_total_obtained numeric(6,2);
    v_pct numeric(5,2);
    v_has_failed boolean;
    v_grade text;
    v_status text;
    v_computed_count int := 0;
    v_pass_count int := 0;
    v_fail_count int := 0;
BEGIN
    IF NOT is_admin() THEN
        RAISE EXCEPTION 'Access denied. Administrator privilege required to compute results.';
    END IF;

    SELECT * INTO v_exam FROM exams WHERE id = p_exam_id AND deleted_at IS NULL;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Exam with ID % does not exist or has been deleted.', p_exam_id;
    END IF;

    -- Calculate total maximum possible marks across all exam subjects
    SELECT coalesce(sum(max_marks), 0) INTO v_total_max
    FROM exam_subjects
    WHERE exam_id = p_exam_id AND deleted_at IS NULL;

    IF v_total_max <= 0 THEN
        RAISE EXCEPTION 'Exam has no configured subjects or maximum marks.';
    END IF;

    -- Loop through all students who have entered marks for this exam
    FOR v_student IN 
        SELECT DISTINCT student_id 
        FROM marks 
        WHERE exam_id = p_exam_id AND deleted_at IS NULL
    LOOP
        v_total_obtained := 0;
        v_has_failed := false;

        -- Verify every subject in this exam
        FOR v_mark IN
            SELECT es.id as subject_id, es.pass_marks, es.max_marks,
                   m.marks_obtained, m.is_absent
            FROM exam_subjects es
            LEFT JOIN marks m ON m.subject_id = es.id 
                             AND m.student_id = v_student.student_id 
                             AND m.exam_id = p_exam_id 
                             AND m.deleted_at IS NULL
            WHERE es.exam_id = p_exam_id AND es.deleted_at IS NULL
        LOOP
            IF v_mark.is_absent = true OR v_mark.marks_obtained IS NULL THEN
                v_has_failed := true;
            ELSE
                v_total_obtained := v_total_obtained + v_mark.marks_obtained;
                IF v_mark.marks_obtained < v_mark.pass_marks THEN
                    v_has_failed := true;
                END IF;
            END IF;
        END LOOP;

        v_pct := round((v_total_obtained / v_total_max) * 100.0, 2);

        -- Determine grade based on configured grading scheme
        SELECT grade INTO v_grade
        FROM grading_schemes
        WHERE v_pct >= min_percent AND v_pct <= max_percent
        ORDER BY min_percent DESC
        LIMIT 1;

        IF v_grade IS NULL THEN
            v_grade := CASE WHEN v_has_failed THEN 'F' ELSE 'C' END;
        END IF;

        IF v_has_failed THEN
            v_status := 'FAIL';
            v_fail_count := v_fail_count + 1;
        ELSE
            v_status := 'PASS';
            v_pass_count := v_pass_count + 1;
        END IF;

        -- Upsert into results with period_type and period_no
        INSERT INTO results (
            exam_id, student_id, total_marks, percentage, grade, status,
            period_type, period_no,
            created_at, updated_at, deleted_at, deleted_by
        )
        VALUES (
            p_exam_id, v_student.student_id, v_total_obtained, v_pct, v_grade, v_status,
            v_exam.period_type, v_exam.period_no,
            clock_timestamp(), clock_timestamp(), NULL, NULL
        )
        ON CONFLICT (exam_id, student_id)
        DO UPDATE SET
            total_marks = EXCLUDED.total_marks,
            percentage = EXCLUDED.percentage,
            grade = EXCLUDED.grade,
            status = EXCLUDED.status,
            period_type = EXCLUDED.period_type,
            period_no = EXCLUDED.period_no,
            deleted_at = NULL,
            deleted_by = NULL,
            updated_at = clock_timestamp();

        v_computed_count := v_computed_count + 1;
    END LOOP;

    -- Compute and assign academic rank among PASS students
    WITH ranked AS (
        SELECT id, rank() OVER (ORDER BY total_marks DESC) as rk
        FROM results
        WHERE exam_id = p_exam_id AND status = 'PASS' AND deleted_at IS NULL
    )
    UPDATE results r
    SET rank = ranked.rk,
        updated_at = clock_timestamp()
    FROM ranked
    WHERE r.id = ranked.id;

    RETURN jsonb_build_object(
        'success', true,
        'computed_students', v_computed_count,
        'passed', v_pass_count,
        'failed', v_fail_count
    );
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;


-- -----------------------------------------------------------------------------
-- 13. RECONCILIATION & AUDIT FUNCTION
-- -----------------------------------------------------------------------------

CREATE OR REPLACE FUNCTION get_migration_reconciliation_report()
RETURNS jsonb AS $$
DECLARE
    v_report jsonb;
    v_unparsed_exams jsonb;
BEGIN
    SELECT coalesce(jsonb_agg(jsonb_build_object(
        'id', id,
        'name', name,
        'course_id', course_id,
        'batch_id', batch_id,
        'raw_semester_text', semester
    )), '[]'::jsonb)
    INTO v_unparsed_exams
    FROM exams
    WHERE period_no IS NULL AND deleted_at IS NULL;

    SELECT jsonb_build_object(
        'courses_count', (SELECT count(*) FROM courses WHERE deleted_at IS NULL),
        'course_subjects_count', (SELECT count(*) FROM course_subjects WHERE deleted_at IS NULL),
        'batches_count', (SELECT count(*) FROM batches WHERE deleted_at IS NULL),
        'batch_periods_count', (SELECT count(*) FROM batch_periods),
        'exams_total', (SELECT count(*) FROM exams WHERE deleted_at IS NULL),
        'exams_parsed_period', (SELECT count(*) FROM exams WHERE period_no IS NOT NULL AND deleted_at IS NULL),
        'exams_unparsed_period', (SELECT count(*) FROM exams WHERE period_no IS NULL AND deleted_at IS NULL),
        'unparsed_exams_list', v_unparsed_exams,
        'results_count', (SELECT count(*) FROM results WHERE deleted_at IS NULL),
        'attendance_sessions_count', (SELECT count(*) FROM attendance_sessions),
        'timestamp', clock_timestamp()
    ) INTO v_report;

    RETURN v_report;
END;
$$ LANGUAGE plpgsql STABLE SECURITY DEFINER;

